// Scratchpad / Design Notes

// 1. Goal: Create a basic Go web server using the standard `net/http` package.
//    The server must handle both GET and POST HTTP methods.

// 2. Core Package: `net/http` is the standard library package for building HTTP servers and clients in Go.
//    We'll also need `fmt` for output, `log` for logging errors, `encoding/json` for handling JSON data (for POST), and `io` for reading the request body.

// 3. Server Structure:
//    - `main` function: Entry point. Responsible for setting up routes and starting the HTTP server.
//    - Handler functions: Separate functions for each route/endpoint. Each handler takes `http.ResponseWriter` and `*http.Request` as arguments.
//    - Routing: Use `http.HandleFunc` to map URL paths to specific handler functions.
//    - Server Startup: Use `http.ListenAndServe` to start the server on a specific port (e.g., 8080).

// 4. API Endpoints:
//    - GET `/`: A root endpoint returning a simple welcome message (text/plain).
//        - Handler: `rootHandler`
//        - Method Check: Ensure only GET requests are accepted.
//    - GET `/status`: An endpoint returning server status (e.g., "Server is running") as JSON.
//        - Handler: `statusHandler`
//        - Method Check: Ensure only GET requests are accepted.
//        - Response: JSON `{"status": "running"}`.
//    - POST `/data`: An endpoint to receive JSON data and echo it back.
//        - Handler: `dataHandler`
//        - Method Check: Ensure only POST requests are accepted.
//        - Request Body: Expects JSON like `{"message": "some data"}`.
//        - Processing: Read the request body, unmarshal JSON into a struct, handle potential errors (bad request format, invalid JSON).
//        - Response: JSON echoing the received message `{"received": {"message": "some data"}}`.

// 5. Error Handling:
//    - Use `http.Error` to send standard HTTP error responses (e.g., 405 Method Not Allowed, 400 Bad Request, 500 Internal Server Error).
//    - Log fatal errors during server startup.
//    - Check for errors when reading request body and unmarshalling JSON.

// 6. Data Structures (for JSON):
//    - Define Go structs to represent the expected JSON payload for the POST request and the JSON responses.
//    - Use `json:"..."` struct tags for mapping Go fields to JSON keys.

// --- End of Scratchpad ---
```

```go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
)

// Structure for receiving data in POST requests
type RequestData struct {
	Message string `json:"message"`
}

// Structure for sending JSON responses
type StatusResponse struct {
	Status string `json:"status"`
}

type DataResponse struct {
	Received RequestData `json:"received"`
}

// Handler for the root endpoint (GET /)
func rootHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}
	// Set content type to plain text
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	fmt.Fprintln(w, "Welcome to the Go Web Server!")
}

// Handler for the status endpoint (GET /status)
func statusHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}

	// Prepare the JSON response
	response := StatusResponse{Status: "running"}
	w.Header().Set("Content-Type", "application/json")
	err := json.NewEncoder(w).Encode(response)
	if err != nil {
		// Log the error server-side, but send a generic error to the client
		log.Printf("Error encoding status response: %v", err)
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
	}
}

// Handler for the data endpoint (POST /data)
func dataHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}

	// Read the request body
	body, err := io.ReadAll(r.Body)
	if err != nil {
		log.Printf("Error reading request body: %v", err)
		http.Error(w, "Bad Request - Cannot read body", http.StatusBadRequest)
		return
	}
	defer r.Body.Close() // Good practice to close the body

	// Unmarshal JSON data
	var requestData RequestData
	err = json.Unmarshal(body, &requestData)
	if err != nil {
		log.Printf("Error unmarshalling JSON: %v", err)
		http.Error(w, "Bad Request - Invalid JSON format", http.StatusBadRequest)
		return
	}

