```cpp
#include <iostream>
#include <string>
#include <stdexcept> // Required for exception types

bool isDoubleOutOfRange_stod(const std::string& numStr, double& outValue) {
    try {
        size_t charsProcessed = 0;
        outValue = std::stod(numStr, &charsProcessed);

        // Optional: Check if the entire string was consumed.
        // std::stod stops at the first character that cannot be part of the number.
        // If you need to ensure the *entire* string is the number, add this check:
        if (charsProcessed != numStr.length()) {
