             // For this example, let's focus on the range check.
             std::cerr << "Warning: Trailing characters found in string: " << numStr << std::endl;
        }

        // If no exception was thrown, the number is convertible and within range
        // (at least for overflow; underflow might result in 0.0).
        return false;
    } catch (const std::out_of_range& oor) {
        // The number was outside the representable range of double.
        std::cerr << "Error: Number '" << numStr << "' is out of range for double. " << oor.what() << std::endl;
        return true;
    } catch (const std::invalid_argument& ia) {
        // The string couldn't be parsed as a double at all.
        std::cerr << "Error: Input '" << numStr << "' is not a valid number. " << ia.what() << std::endl;
        return true; // Or handle as a different kind of error
    }
}

