import "std";

// Modular exponentiation (base^exp % mod)
// Computes (base^exp) % mod efficiently.
fn modPow(base: u64, exp: u64, mod: u64) u64 {
    // Modulus must be > 0. If mod is 1, result is always 0.
    if (mod == 0) @panic("modulus cannot be zero");
    if (mod == 1) return 0;

    var result: u128 = 1; // Use u128 for intermediate multiplication result
    var b: u128 = base % mod;
    var e = exp;

    while (e > 0) {
        // If exponent is odd, multiply result with base
        if (e % 2 == 1) {
            result = (result * b) % mod;
        }
        // Divide exponent by 2
        e >>= 1;
        // Square the base
        b = (b * b) % mod;
    }
    // The final result fits in u64 as it's < mod (which fits in u64)
    return @intCast(u64, result);
}

// Parses the input string to find the row and column numbers.
// Looks for "row R" and "column C" patterns.
fn parseRowCol(allocator: std.mem.Allocator, input: []const u8) !struct { row: u64, col: u64 } {
    _ = allocator; // Allocator not needed for this simple parsing method
    var row: u64 = 0;
    var col: u64 = 0;
    var row_found = false;
    var col_found = false;

    var stream = std.io.fixedBufferStream(input);
    const reader = stream.reader();
    var buf: [1024]u8 = undefined; // Buffer for reading words/tokens
    var tokenizer = std.fmt.tokenizer(reader, buf[0..]);

    while (try tokenizer.next()) |token| {
        // Check if the token is "row"
        if (std.mem.eql(u8, token, "row")) {
            // Expect the next token to be the row number
            if (try tokenizer.next()) |num_token| {
                // Clean potential trailing punctuation (like ',' or '.')
                var clean_token = num_token;
                if (clean_token.len > 0) {
                    const last_char = clean_token[clean_token.len - 1];
                    if (last_char == '.' or last_char == ',') {
                        clean_token = clean_token[0 .. clean_token.len - 1];
                    }
                }
                // Parse the number
                row = try std.fmt.parseInt(u64, clean_token, 10);
                row_found = true;
            } else {
                std.debug.print("Error: Found 'row' but no following number.\n", .{});
                return error.ParseError;
            }
        // Check if the token is "column"
        } else if (std.mem.eql(u8, token, "column")) {
            // Expect the next token to be the column number
            if (try tokenizer.next()) |num_token| {
                 // Clean potential trailing punctuation
                 var clean_token = num_token;
                 if (clean_token.len > 0) {
                    const last_char = clean_token[clean_token.len - 1];
                    if (last_char == '.' or last_char == ',') {
                        clean_token = clean_token[0 .. clean_token.len - 1];
                    }
                 }
                 // Parse the number
                 col = try std.fmt.parseInt(u64, clean_token, 10);
                 col_found = true;
            } else {
                std.debug.print("Error: Found 'column' but no following number.\n", .{});
                return error.ParseError;
            }
        }
        // Stop if both numbers are found
        if (row_found and col_found) break;
    }

    // Check if both numbers were successfully parsed
    if (!row_found or !col_found) {
         std.debug.print("Error: Could not find both 'row' and 'column' numbers in the input file.\n", .{});
         return error.ParseError;
    }

    return .{ .row = row, .col = col };
}


pub fn main() !void {
    // Use a general-purpose allocator for file reading
    const allocator = std.heap.page_allocator;

    // 1. Read input from "input.txt"
    const file_path = "input.txt";
    var file: std.fs.File = undefined;
    file = try std.fs.cwd().openFile(file_path, .{ .read = true });
    defer file.close();

    // Read the entire file content, with a safety limit (e.g., 1MB)
    const max_input_size = 1 * 1024 * 1024;
    const input_bytes = try file.readToEndAlloc(allocator, max_input_size);
    defer allocator.free(input_bytes);

    // 2. Parse the target row and column
    const coords = try parseRowCol(allocator, input_bytes);
    const target_row = coords.row;
    const target_col = coords.col;

    // 3. Calculate the position index N (1-based) in the sequence
    // The code at (row, col) is on diagonal d = row + col - 1.
    // The number of codes before this diagonal is Sum(1..d-1) = (d-1)*d / 2.
    // The position within the diagonal is given by the column number 'col'.
    // The 1-based index N = [(d-1)*d / 2] + col.
    const d = target_row + target_col - 1;

    // Calculate sum 1..d-1 safely. Note: (d-1)*d can exceed u64 max if d is large enough,
    // but for reasonable AoC inputs (row/col < ~4M), d < ~8M, d^2 < 64e12 << 18e18 (u64 max), so overflow is unlikely.
    // Using u128 temporarily for calculation provides extra safety margin.
    const d128: u128 = d;
    const prev_diag_sum: u64 = if (d < 2) 0 else @intCast(u64, ((d128 - 1) * d128) / 2);

    const index_n: u64 = prev_diag_sum + target_col;

    // 4. Calculate the code value using the recurrence relation
    // code(n) = (code(n-1) * multiplier) % modulus
    // => code(N) = (code(1) * multiplier^(N-1)) % modulus
    const start_code: u64 = 20151125;
    const multiplier: u64 = 252533;
    const modulus: u64 = 33554393;

    // The exponent for the multiplier is N-1
    const exponent = index_n - 1;

    // Calculate multiplier^(N-1) % modulus using modular exponentiation
    const factor = modPow(multiplier, exponent, modulus);

    // Calculate the final code: (start_code * factor) % modulus
    // Use u128 for intermediate multiplication to prevent overflow before modulo.
    const final_code: u64 = @intCast(u64, (@as(u128, start_code) * @as(u128, factor)) % modulus);

    // 5. Print the final code to stdout
    const stdout_writer = std.io.getStdOut().writer();
    try stdout_writer.print("{d}\n", .{final_code});
}
