    const file_contents = try file.readToEndAlloc(arena_allocator, std.math.maxInt(usize)); // Read up to system max usize

    // --- 2. Parse row and column ---
    // Use regex to find "row X" and "column Y" regardless of order in the text.
    // (?s) allows '.' to match newlines. Non-greedy '.*?' handles potential multiple number pairs.
    const re_pattern = "(?s).*?row (\\d+).*?column (\\d+)";
    var re = try std.regex.Regex.compile(arena_allocator, re_pattern);
    defer re.deinit(); // This Regex doesn't strictly need deinit with arena, but good practice

    var row: u64 = undefined;
    var col: u64 = undefined;

    // Try matching "row ..., column ..."
    if (re.match(file_contents)) |captures| {
        row = try std.fmt.parseUnsigned(u64, captures.captures[0].?, 10);
        col = try std.fmt.parseUnsigned(u64, captures.captures[1].?, 10);
    } else {
        // If first pattern failed, try matching "column ..., row ..."
        const re_pattern_swapped = "(?s).*?column (\\d+).*?row (\\d+)";
        re = try std.regex.Regex.compile(arena_allocator, re_pattern_swapped); // Recompile
        if (re.match(file_contents)) |captures| {
            col = try std.fmt.parseUnsigned(u64, captures.captures[0].?, 10);
            row = try std.fmt.parseUnsigned(u64, captures.captures[1].?, 10);
        } else {
            std.debug.print("Error: Could not find row and column numbers in input.txt\n", .{});
            return error.InputParseError;
        }
    }

    // --- 3. Calculate the position index (N) ---
    // The index N (1-based) for code at (row, col) is calculated based on diagonals.
    // Diagonal number d = row + col - 1
    // Number of elements before this diagonal = sum(1 to d-1) = (d-1)*d / 2
    // Position within the diagonal = col
    const diag: u64 = row + col - 1;
    const n: u64 = (diag * (diag - 1)) / 2 + col;

    // --- 4. Calculate the code ---
    // The code at index N is C_N = (start_value * base^(N-1)) % mod_value
    // We need N-1 steps of multiplication from the start value.
    if (n == 0) {
        // This case should not happen with valid row/col >= 1
        std.debug.print("Error: Calculated index is zero.\n", .{});
        return error.InvalidIndex;
    }
    const exponent = n - 1;

    const pow_val = modPow(base, exponent, mod_value);

    // Calculate final code. Multiplication (start_value * pow_val) could exceed u64.max
    // if start_value or pow_val were close to u64.max, but here they are < mod_value,
    // so their product < mod_value^2, which fits in u64. Direct u64 multiplication is safe.
    const code = (start_value * pow_val) % mod_value;

    // --- 5. Print the result ---
    const stdout_writer = std.io.getStdOut().writer();
    try stdout_writer.print("{d}\n", .{code});
}
```

