import React, { useState, useMemo, useRef, useEffect, useCallback, ChangeEvent, KeyboardEvent, FocusEvent } from 'react';

// Simple debounce utility
function debounce<T extends (...args: any[]) => void>(func: T, wait: number) {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  return (...args: Parameters<T>): void => {
    if (timeoutId) clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      func(...args);
    }, wait);
  };
}

interface AutocompleteProps {
  options: string[];
  value?: string;
  onChange?: (value: string) => void;
  validate?: (value: string) => boolean;
  placeholder?: string;
  debounceWait?: number;
}

export const AutocompleteInput: React.FC<AutocompleteProps> = ({
  options,
  value: controlledValue,
  onChange,
  validate = () => true, // Default to always valid if no validator provided
  placeholder = 'Type to search...',
  debounceWait = 300,
}) => {
  const [internalValue, setInternalValue] = useState<string>('');
  const isControlled = controlledValue !== undefined && onChange !== undefined;
  const inputValue = isControlled ? controlledValue : internalValue;

  const [filteredOptions, setFilteredOptions] = useState<string[]>([]);
  const [showDropdown, setShowDropdown] = useState<boolean>(false);
  const [isValid, setIsValid] = useState<boolean>(true);
  const [activeIndex, setActiveIndex] = useState<number>(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listboxRef = useRef<HTMLUListElement>(null); // For accessibility

  // Memoized debounced filtering function
  const debouncedFilterOptions = useMemo(() =>
    debounce((currentInput: string) => {
      const lowerInput = currentInput.toLowerCase().trim();
      let newFilteredOptions: string[] = [];
      if (lowerInput) {
        newFilteredOptions = options.filter(opt =>
          opt.toLowerCase().includes(lowerInput)
        );
      }
      setFilteredOptions(newFilteredOptions);
      setShowDropdown(newFilteredOptions.length > 0);
      setActiveIndex(-1); // Reset index on new filter results
    }, debounceWait),
    [options, debounceWait]
  );

  // Validation function
  const runValidation = useCallback((currentInput: string) => {
    setIsValid(validate(currentInput));
  }, [validate]);

  // Input change handler
  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value;
    if (isControlled) {
      onChange(newValue);
    } else {
      setInternalValue(newValue);
    }
    debouncedFilterOptions(newValue);
    runValidation(newValue); // Validate as user types
  };

  // Option selection handler
  const handleOptionSelect = (option: string) => {
    if (isControlled) {
      onChange(option);
    } else {
      setInternalValue(option);
    }
    setFilteredOptions([]); // Clear filter
    setShowDropdown(false);
    runValidation(option); // Validate selected value
    inputRef.current?.focus();
  };

  // Keyboard navigation handler
  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (!showDropdown || filteredOptions.length === 0) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex(prev => (prev < filteredOptions.length - 1 ? prev + 1 : 0));
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex(prev => (prev > 0 ? prev - 1 : filteredOptions.length - 1));
        break;
      case 'Enter':
        e.preventDefault();
        if (activeIndex >= 0) {
          handleOptionSelect(filteredOptions[activeIndex]);
        }
        break;
      case 'Escape':
        setShowDropdown(false);
        setActiveIndex(-1);
        break;
      default:
        setActiveIndex(-1); // Reset index if typing other keys
        break;
    }
  };

    // Scroll active item into view
    useEffect(() => {
        if (activeIndex >= 0 && listboxRef.current) {
            const activeItem = listboxRef.current.children[activeIndex] as HTMLLIElement | undefined;
            activeItem?.scrollIntoView?.({ block: 'nearest' });
        }
    }, [activeIndex]);


  // Focus/Blur handler for dropdown visibility
    const handleFocus = () => {
        // Re-filter on focus if needed, show dropdown if matches exist
        debouncedFilterOptions(inputValue);
        runValidation(inputValue);
    };

    const handleBlur = (e: FocusEvent<HTMLDivElement>) => {
        // Use relatedTarget to prevent closing when clicking inside the dropdown
        if (containerRef.current && !containerRef.current.contains(e.relatedTarget as Node)) {
            setShowDropdown(false);
            setActiveIndex(-1);
            // Optionally, validate on blur as well/instead
            // runValidation(inputValue);
        }
    };

  return (
    <div
        ref={containerRef}
        style={{ position: 'relative', width: '300px' }}
        onFocus={handleFocus} // Attach focus to container
        onBlur={handleBlur}  // Attach blur to container
        role="combobox"
        aria-expanded={showDropdown}
        aria-haspopup="listbox"
        aria-owns="autocomplete-listbox" // Links combobox to listbox
    >
      <input
        ref={inputRef}
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        style={{
          width: '100%',
          padding: '8px',
          boxSizing: 'border-box',
          border: isValid ? '1px solid #ccc' : '1px solid red',
          borderRadius: '4px',
        }}
        aria-autocomplete="list"
        aria-controls="autocomplete-listbox" // Links input to listbox
        aria-activedescendant={activeIndex >= 0 ? `option-${activeIndex}` : undefined} // Points to active option
        aria-invalid={!isValid}
      />
      {showDropdown && (
        <ul
          ref={listboxRef}
          id="autocomplete-listbox" // ID for aria-controls/owns
          role="listbox"
          style={{
            position: 'absolute', top: '100%', left: 0, right: 0,
            maxHeight: '200px', overflowY: 'auto', listStyle: 'none',
            margin: 0, padding: 0, border: '1px solid #ccc', borderTop: 'none',
            backgroundColor: '#fff', zIndex: 1000,
          }}
        >
          {/* Virtualization could be added here */}
          {filteredOptions.map((option, index) => (
            <li
              key={option} // Assuming options are unique strings
              id={`option-${index}`} // ID for aria-activedescendant
              role="option"
              aria-selected={index === activeIndex}
              style={{
                padding: '8px', cursor: 'pointer',
                backgroundColor: index === activeIndex ? '#f0f0f0' : '#fff',
              }}
              onMouseDown={(e) => e.preventDefault()} // Prevent input blur before click registers
              onClick={() => handleOptionSelect(option)}
              onMouseEnter={() => setActiveIndex(index)}
            >
              {option}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

