using System.Collections.Generic;
using System.IO;

namespace StudentDataApp
{
    // Handles reading and writing student data to a binary file.
    public static class StudentDB
    {
        // Define the directory and file path for storing data.
        // Ensure this directory exists or the application has permissions to create it.
        private const string Dir = @"C:\C#\files\StudentData\";
        private const string Path = Dir + "Students.dat";

        // Saves a list of students to the binary file, overwriting existing data.
        public static void SaveStudents(List<Student> students)
        {
            // Ensure the directory exists before writing.
            if (!Directory.Exists(Dir))
                Directory.CreateDirectory(Dir);

            // Use BinaryWriter within a using statement for proper disposal.
            using (BinaryWriter writer = new BinaryWriter(
                new FileStream(Path, FileMode.Create, FileAccess.Write)))
            {
                // Write each student's data to the file.
                foreach (Student student in students)
                {
                    writer.Write(student.StudentID); // Write integer ID
                    writer.Write(student.Name);      // Write string Name
                    writer.Write(student.GPA);       // Write decimal GPA
                }
            } // FileStream and BinaryWriter are automatically closed here.
        }

        // Reads all students from the binary file.
        public static List<Student> GetStudents()
        {
            List<Student> students = new List<Student>();

            // Ensure the directory exists before attempting to read.
            if (!Directory.Exists(Dir))
                Directory.CreateDirectory(Dir);

            // Check if the file exists before trying to open it for reading.
            if (File.Exists(Path))
            {
                // Use BinaryReader within a using statement for proper disposal.
                using (BinaryReader reader = new BinaryReader(
                    new FileStream(Path, FileMode.Open, FileAccess.Read)))
                {
                    // Read until the end of the file is reached.
                    // Checking position against length is safer than PeekChar for binary data.
                    while (reader.BaseStream.Position < reader.BaseStream.Length)
                    {
                        try
                        {
                            // Read data in the same order it was written.
                            int id = reader.ReadInt32();
                            string name = reader.ReadString();
                            decimal gpa = reader.ReadDecimal();

                            // Create and add the student to the list.
                            Student student = new Student { StudentID = id, Name = name, GPA = gpa };
                            students.Add(student);
                        }
                        catch (EndOfStreamException)
                        {
                            // Reached the end unexpectedly (e.g., corrupted file).
                            // Handle appropriately, maybe log an error or break.
                            System.Windows.Forms.MessageBox.Show("Error reading file: Unexpected end of stream.", "File Read Error", System.Windows.Forms.MessageBoxButtons.OK, System.Windows.Forms.MessageBoxIcon.Warning);
                            break; // Exit the loop
                        }
                        catch (IOException ex)
                        {
                            // Handle other potential I/O errors during reading.
                            System.Windows.Forms.MessageBox.Show($"Error reading file: {ex.Message}", "File Read Error", System.Windows.Forms.MessageBoxButtons.OK, System.Windows.Forms.MessageBoxIcon.Error);
                            break; // Exit the loop
                        }
                    }
                } // FileStream and BinaryReader are automatically closed here.
            }
            // If the file doesn't exist, return an empty list.
            return students;
        }
    }
}
