```rust
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")] // hide console window on Windows in release

use eframe::{egui, App, Frame};
use notify::{Config, EventKind, RecommendedWatcher, RecursiveMode, Watcher};
use rfd::FileDialog;
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread::{self, JoinHandle};
use crossbeam_channel::{unbounded, Receiver, Sender}; // Using crossbeam for good performance

// --- Application State ---
struct FolderMonitorApp {
    input_folder: Option<PathBuf>,
    output_folder: Option<PathBuf>,
    done_folder: Option<PathBuf>,
    event_log: Vec<String>,
    monitoring_active: bool,
    // Communication from watcher thread to GUI thread
    event_receiver: Receiver<String>,
    // Sender is kept by the struct only to be cloned for the watcher thread
    event_sender: Sender<String>,
    // Signalling the watcher thread to stop
    stop_signal: Arc<AtomicBool>,
    // Handle to the watcher thread for joining
    watcher_thread_handle: Option<JoinHandle<()>>,
}

impl FolderMonitorApp {
    fn new(_cc: &eframe::CreationContext<'_>) -> Self {
        let (sender, receiver) = unbounded();
        Self {
            input_folder: None,
            output_folder: None,
            done_folder: None,
            event_log: Vec::new(),
            monitoring_active: false,
            event_receiver: receiver,
            event_sender: sender,
            stop_signal: Arc::new(AtomicBool::new(false)),
            watcher_thread_handle: None,
        }
    }

    fn start_monitoring(&mut self) {
        if self.monitoring_active {
            self.log_message("Monitoring is already active.");
            return;
        }

        // Use let-else for cleaner code
        let Some(input_path) = self.input_folder.clone() else {
            self.log_message("Error: Input folder not selected.");
            return;
        };

        self.log_message(format!("Starting monitoring on: {}", input_path.display()));

        let sender_clone = self.event_sender.clone();
        let stop_signal_clone = Arc::clone(&self.stop_signal);
        // Reset stop signal before starting
        stop_signal_clone.store(false, Ordering::Relaxed);

        let handle = thread::spawn(move || {
            // Event handler closure for RecommendedWatcher
            let event_handler = move |res: Result<notify::Event, notify::Error>| {
                match res {
                    Ok(event) => {
                        // Filter for create events specifically, as requested
                        if event.kind.is_create() {
                            let paths: Vec<String> = event.paths.iter()
                                .map(|p| p.display().to_string())
                                .collect();
                            if !paths.is_empty() {
                                let msg = format!("New file detected: {}", paths.join(", "));
                                // Send message to GUI thread, handle potential send error
                                if sender_clone.send(msg).is_err() {
                                    // Receiver likely dropped (GUI closed), log error
                                    eprintln!("GUI channel closed while trying to send event.");
                                }
                            }
                        }
                        // Optionally log other event types if needed
                        // else {
                        //     println!("Other event: {:?}", event);
                        // }
                    }
                    Err(e) => {
                        let msg = format!("Watch error: {:?}", e);
                        if sender_clone.send(msg).is_err() {
                           eprintln!("GUI channel closed while trying to send error.");
                        }
                    }
                }
            };

            // It's important to handle potential errors during watcher creation
            let mut watcher = match RecommendedWatcher::new(event_handler, Config::default()) {
                Ok(w) => w,
                Err(e) => {
                    let _ = sender_clone.send(format!("Error creating watcher: {}", e));
                    return; // Exit thread if watcher creation fails
                }
            };

            // Add the path to be watched.
            if let Err(e) = watcher.watch(&input_path, RecursiveMode::NonRecursive) {
                 let _ = sender_clone.send(format!("Error starting watch on {}: {}", input_path.display(), e));
                 return; // Exit thread if watching fails
            }

            // Keep the thread alive and responsive to the stop signal
            // RecommendedWatcher runs its own event loop, we just need to keep this thread
            // alive until signaled to stop, allowing the watcher object to stay in scope.
            loop {
                if stop_signal_clone.load(Ordering::Relaxed) {
                     let _ = sender_clone.send("Monitoring stop requested.".to_string());
                     break; // Exit loop if stop signal is set
                }
                // Sleep briefly to avoid busy-waiting
                thread::sleep(std::time::Duration::from_millis(200));
            }

            // Unwatch the path when stopping
             if let Err(e) = watcher.unwatch(&input_path) {
                  let _ = sender_clone.send(format!("Error unwatching path: {}", e));
             }
             let _ = sender_clone.send("Monitoring stopped.".to_string());
        });

        self.watcher_thread_handle = Some(handle);
        self.monitoring_active = true;
    }

    fn stop_monitoring(&mut self) {
        if !self.monitoring_active {
            self.log_message("Monitoring is not active.");
            return;
        }

        self.log_message("Stopping monitoring...");
        // Signal the thread to stop
        self.stop_signal.store(true, Ordering::Relaxed);

        // Wait for the thread to finish
        if let Some(handle) = self.watcher_thread_handle.take() {
            match handle.join() {
                Ok(_) => self.log_message("Watcher thread joined successfully."), // This message might arrive *after* "Monitoring stopped." from the thread itself.
                Err(_) => self.log_message("Error joining watcher thread."),
            }
        } else {
             self.log_message("Warning: No watcher thread handle found to join.");
        }

        self.monitoring_active = false;
        // Drain any remaining messages after stopping
        self.drain_event_channel();
    }

    // Helper to add messages to the log
    fn log_message(&mut self, message: impl Into<String>) {
        self.event_log.push(message.into());
        // Optional: Limit log size
        const MAX_LOG_LINES: usize = 100;
        if self.event_log.len() > MAX_LOG_LINES {
            self.event_log.drain(0..self.event_log.len() - MAX_LOG_LINES);
        }
    }

    // Helper to drain messages from the channel
    fn drain_event_channel(&mut self) {
        while let Ok(msg) = self.event_receiver.try_recv() {
            self.log_message(msg);
        }
    }
}


