    // Method to start the file monitoring thread
    fn start_monitoring(&mut self, ctx: &egui::Context) {
        if self.is_monitoring {
            self.log_message("Monitoring is already active.".to_string());
            return;
        }
        // Ensure input path is selected
        guard!(let Some(input_path) = self.input_path.clone() else {
            self.log_message("Error: Input folder must be selected before starting.".to_string());
            return;
        });

        // Reset stop signal and create channel
        self.stop_signal.store(false, Ordering::Relaxed);
        let stop_signal_clone = Arc::clone(&self.stop_signal);
        let (log_tx, log_rx) = mpsc::channel();
        self.log_rx = Some(log_rx);
        // Clone egui context to request repaints from the thread
        let egui_ctx = ctx.clone();

        self.log_message(format!("Attempting to monitor: {}", input_path.display()));

        // Spawn the watcher thread
        let handle = thread::spawn(move || {
            // Create sender clone for the watcher callback
            let watcher_log_tx = log_tx.clone();
            // Create the file system watcher using notify's recommended watcher
            let mut watcher = match RecommendedWatcher::new(
                move |res: Result<notify::Event, notify::Error>| {
                    match res {
                        Ok(event) => {
                            // Check if it's a file creation event
                            if event.kind.is_create() {
                                for path in event.paths {
                                    // Send message to GUI thread
                                    let _ = watcher_log_tx.send(format!("New file: {}", path.display()));
                                    // Request the GUI thread to repaint to show the new message
                                    egui_ctx.request_repaint();
                                }
                            }
                            // Note: Could log other events (modify, remove) here if needed
                        }
                        Err(e) => {
                            // Send error message to GUI thread
                            let _ = watcher_log_tx.send(format!("Notify error: {}", e));
                            egui_ctx.request_repaint();
                        }
                    }
                },
                Config::default(), // Use default notify configuration
            ) {
                Ok(w) => w,
                Err(e) => {
                    // Send error message and exit thread if watcher creation fails
                    let _ = log_tx.send(format!("Error creating watcher: {}", e));
                    egui_ctx.request_repaint();
                    return;
                }
            };

            // Start watching the specified input path (non-recursively)
            if let Err(e) = watcher.watch(&input_path, RecursiveMode::NonRecursive) {
                // Send error message and exit thread if watching fails
                let _ = log_tx.send(format!("Error watching path {}: {}", input_path.display(), e));
                egui_ctx.request_repaint();
                return;
            }

            // Log success
            let _ = log_tx.send(format!("Started monitoring: {}", input_path.display()));
            egui_ctx.request_repaint();

            // Loop to keep the thread alive while checking the stop signal
            loop {
                if stop_signal_clone.load(Ordering::Relaxed) {
                    let _ = log_tx.send("Stop signal received.".to_string());
                    egui_ctx.request_repaint();
                    break; // Exit loop if stop signal is set
                }
                // Sleep briefly to prevent busy-waiting; events are handled by the callback
                thread::sleep(Duration::from_millis(500));
            }

            // --- Cleanup ---
            // Unwatch the path explicitly
            if let Err(e) = watcher.unwatch(&input_path) {
                // Log error (could also send to GUI)
                eprintln!("Error unwatching path {}: {}", input_path.display(), e);
                let _ = log_tx.send(format!("Error unwatching path {}: {}", input_path.display(), e));
                 egui_ctx.request_repaint();
            }
            let _ = log_tx.send("Monitoring stopped.".to_string());
            egui_ctx.request_repaint();
        });

        // Store thread handle and update state
        self.watcher_thread = Some(handle);
        self.is_monitoring = true;
    }

    // Method to stop the file monitoring thread
    fn stop_monitoring(&mut self) {
        if !self.is_monitoring {
            return; // Not currently monitoring
        }

        self.log_message("Stopping monitoring...".to_string());
        // Signal the thread to stop
        self.stop_signal.store(true, Ordering::Relaxed);

        // Wait for the thread to finish and join it
        if let Some(handle) = self.watcher_thread.take() {
            if let Err(e) = handle.join() {
                // Log error if joining fails
                eprintln!("Error joining watcher thread: {:?}", e);
                self.log_message(format!("Error joining watcher thread: {:?}", e));
            }
        }

        // Update state
        self.is_monitoring = false;
        // Drop the receiver to close the channel from the GUI side
        self.log_rx = None;
        self.log_message("Monitoring ended.".to_string());
    }

    // Helper function to add messages to the log and limit its size
    fn log_message(&mut self, msg: String) {
        self.message_log.push(msg);
        const MAX_LOG_LINES: usize = 100; // Keep only the last 100 messages
        while self.message_log.len() > MAX_LOG_LINES {
            self.message_log.remove(0);
        }
    }
}

