{ config, pkgs, inputs, username, ... }: # username passed from specialArgs

{
  # --- Home Manager Settings ---
  # This MUST be set. Match it with system.stateVersion.
  home.stateVersion = "23.11"; # <<< CHANGE THIS to your NixOS version

  # Let Home Manager know the user and home directory
  home.username = username; # Uses the username variable passed from flake.nix
  home.homeDirectory = "/home/${username}";

  # --- User Packages ---
  # Packages installed specifically for this user
  home.packages = with pkgs; [
    # Add any user-specific tools here if preferred over system-wide install
    # e.g., nodejs, go, gh (GitHub CLI)
  ];

  # --- Shell Configuration (Example: Zsh) ---
  programs.zsh = {
    enable = true; # Ensure Zsh settings are managed by Home Manager
    # Example aliases
    shellAliases = {
      ls = "ls --color=auto";
      ll = "ls -alhF --color=auto";
      l = "ls -CF --color=auto";
      grep = "grep --color=auto";
      # Alias for rebuilding the system from the flake config directory
      nixrebuild = "sudo nixos-rebuild switch --flake /home/${username}/nixos-config#${config.networking.hostName}";
      # Alias for updating just the home-manager config (less common when integrated)
      # hmupdate = "home-manager switch --flake /home/${username}/nixos-config#${username}";
    };
    # Example: Oh My Zsh setup (requires internet during build/switch)
    # oh-my-zsh = {
    #   enable = true;
    #   plugins = [ "git" "sudo" "history" ];
    #   theme = "robbyrussell";
    # };
  };
