#include <stdio.h>

/*
 * Finds the largest index 'i' in a monotonically increasing array 'arr'
 * such that arr[i] < target.
 * A monotonically increasing array means arr[j] >= arr[k] for j > k.
 *
 * Parameters:
 *   arr: Pointer to the monotonically increasing integer array.
 *   n: The number of elements in the array.
 *   target: The target value.
 *
 * Returns:
 *   The largest index 'i' where arr[i] < target.
 *   Returns -1 if no such element exists (e.g., all elements are >= target,
 *   or the array is empty).
 */
int findLargestIndexLessThan(int arr[], int n, int target) {
    // Handle empty array case explicitly for clarity, though the logic below handles it.
    if (n <= 0) {
        return -1;
    }

    int low = 0;
    int high = n - 1;
    int result = -1; // Stores the best index found so far

    // Perform binary search
    while (low <= high) {
        int mid = low + (high - low) / 2; // Prevent potential overflow

        if (arr[mid] < target) {
            // arr[mid] is strictly less than target.
            // This is a potential answer. Store it.
            result = mid;
            // Since we want the *largest* index, try searching in the right half
            // to find a potentially larger index that also satisfies the condition.
            low = mid + 1;
        } else {
            // arr[mid] >= target.
            // The element at mid is too large (or equal), so the desired element
            // must be in the left half.
            high = mid - 1;
        }
    }

    // After the loop, 'result' holds the largest index 'i' such that arr[i] < target,
    // or -1 if no such element was found.
    return result;
}

