        // std::cout << "Node(" << data << ") created." << std::endl; // For demo
    }

    // Destructor (automatically called)
    ~Node() {
        // std::cout << "Node(" << data << ") destroyed." << std::endl; // For demo
        // The unique_ptr 'next' will automatically delete the node it points to
        // when this Node object is destroyed, triggering recursive deletion.
    }
};

// LinkedList class managing the nodes
class LinkedList {
private:
    std::unique_ptr<Node> head; // Smart pointer to the first node

public:
    // Default constructor
    LinkedList() : head(nullptr) {}

    // Destructor (automatically called)
    ~LinkedList() {
        // std::cout << "LinkedList destroyed. Cleaning up nodes..." << std::endl; // For demo
        // When the LinkedList object is destroyed, 'head' (a unique_ptr)
