/**
 * @brief Performs linear interpolation for a value x based on sample points (x_pts, y_pts).
 *
 * Assumes x_pts is sorted in ascending order.
 * Handles extrapolation by clamping to the boundary values (similar to interp1d default without fill_value='extrapolate').
 *
 * @param x The point at which to interpolate.
 * @param x_pts The vector of x-coordinates of the sample points.
 * @param y_pts The vector of y-coordinates of the sample points.
 * @return The interpolated y-value at x.
 */
double linear_interpolate(double x, const std::vector<double>& x_pts, const std::vector<double>& y_pts) {
    if (x_pts.empty() || y_pts.empty() || x_pts.size() != y_pts.size()) {
        throw std::invalid_argument("Input vectors must be non-empty and of the same size.");
    }
    if (x_pts.size() == 1) {
        return y_pts[0]; // Single point case
    }

    // Handle points outside the original range (clamping)
    if (x <= x_pts.front()) {
        return y_pts.front();
    }
    if (x >= x_pts.back()) {
        return y_pts.back();
    }

    // Find the interval [x_pts[i], x_pts[i+1]] containing x
    // `lower_bound` returns an iterator to the first element not less than x.
    auto it = std::lower_bound(x_pts.begin(), x_pts.end(), x);

    // Since we handled x >= x_pts.back() above, it cannot be x_pts.end() here.
    // Since we handled x <= x_pts.front() above, it cannot be x_pts.begin() unless x == x_pts.front().
    size_t idx1 = std::distance(x_pts.begin(), it);

    // If x exactly matches a point in x_pts
     if (std::fabs(*it - x) < 1e-9) { // Use tolerance for float comparison
         return y_pts[idx1];
     }

    // x lies between x_pts[idx1-1] and x_pts[idx1]
    size_t idx0 = idx1 - 1;

    double x0 = x_pts[idx0];
    double x1 = x_pts[idx1]; // *it is x_pts[idx1]
    double y0 = y_pts[idx0];
    double y1 = y_pts[idx1];

    // Avoid division by zero if points are coincident (unlikely with linspace/arange)
    if (std::fabs(x1 - x0) < 1e-9) {
        return y0; // Or y1, or average
    }

    // Calculate interpolation factor 't' and the result
    double t = (x - x0) / (x1 - x0);
    return y0 + t * (y1 - y0);
}

