                else if player1Current == .advantage { currentGame.scorePlayer1 = .forty } // Back to Deuce effectively
                else { completeGame(winner: .player2) }
            case .advantage: completeGame(winner: .player2)
            default: break // Should not happen
            }
        }
        // Ensure consistency if scores went back to 40-40 (Deuce)
        if currentGame.scorePlayer1 == .forty && currentGame.scorePlayer2 == .forty {
           // State remains 40-40, display handles "Deuce"
        }
    }

    private func completeGame(winner: Player) {
        currentGame.isGameComplete = true
        currentGame.winner = winner
    }

    private func updateSetScore() {
        guard let gameWinner = currentGame.winner else { return }
        completedGamesInCurrentSet.append(currentGame) // Store completed game history if needed

        if gameWinner == .player1 {
            sets[currentSetIndex].gamesPlayer1 += 1
        } else {
            sets[currentSetIndex].gamesPlayer2 += 1
        }

        checkSetCompletion()

        if !sets[currentSetIndex].isSetComplete {
            startNewGame()
        } else {
            checkMatchCompletion()
            if matchWinner == nil && currentSetIndex < 2 { // Max 3 sets (indices 0, 1, 2)
                startNewSet()
            }
        }
    }

    private func checkSetCompletion() {
        let currentSet = sets[currentSetIndex]
        let games1 = currentSet.gamesPlayer1
        let games2 = currentSet.gamesPlayer2

        // Basic set completion logic (no tie-break)
        if (games1 >= 6 && games1 >= games2 + 2) || games1 == 7 {
            sets[currentSetIndex].isSetComplete = true
            sets[currentSetIndex].winner = .player1
            setsWonPlayer1 += 1
        } else if (games2 >= 6 && games2 >= games1 + 2) || games2 == 7 {
            sets[currentSetIndex].isSetComplete = true
            sets[currentSetIndex].winner = .player2
            setsWonPlayer2 += 1
        }
        // Note: 7-5 win implemented, but 6-6 goes to 7-6 which is a tie-break usually.
        // Simplified here: first to 7 wins if it's 7-6 or 7-5.
    }

     private func checkMatchCompletion() {
        // Best of 3 sets
        if setsWonPlayer1 == 2 {
            matchWinner = .player1
        } else if setsWonPlayer2 == 2 {
            matchWinner = .player2
        }
     }

    private func startNewGame() {
        currentGame = GameState()
    }

    private func startNewSet() {
        currentSetIndex += 1
        if currentSetIndex < 3 { // Ensure we don't exceed 3 sets
             sets.append(SetState())
             completedGamesInCurrentSet = [] // Reset game history for the new set
             startNewGame()
        }
    }

    func resetMatch() {
        sets = [SetState()]
        currentSetIndex = 0
        currentGame = GameState()
        completedGamesInCurrentSet = []
        matchWinner = nil
        isAdvancedMode = false
        allPointsLog = []
        setsWonPlayer1 = 0
        setsWonPlayer2 = 0
    }
}

