// Represents the state of a single game
class Game: ObservableObject {
    @Published private(set) var points: [PlayerID: Int] = [.player1: 0, .player2: 0]
    @Published private(set) var winner: PlayerID? = nil
    @Published private(set) var isComplete: Bool = false

    var scoreDisplay: String {
        guard !isComplete else { return "Game" }
        guard let p1Pts = points[.player1], let p2Pts = points[.player2] else { return "Error" }

        if p1Pts >= 3 && p2Pts >= 3 {
            if p1Pts == p2Pts { return "Deuce" }
            return (p1Pts > p2Pts) ? "Adv Player 1" : "Adv Player 2"
        } else {
            return "\(tennisScore(p1Pts))-\(tennisScore(p2Pts))"
        }
    }

    private func tennisScore(_ score: Int) -> String {
        switch score {
        case 0: return "Love"
        case 1: return "15"
        case 2: return "30"
        case 3: return "40"
        default: return "N/A" // Should not happen in non-deuce
        }
    }

    func addPoint(for player: PlayerID) {
        guard !isComplete else { return }
        points[player, default: 0] += 1
        checkGameEnd()
    }

    private func checkGameEnd() {
        guard let p1Pts = points[.player1], let p2Pts = points[.player2] else { return }
        if p1Pts >= 4 && p1Pts >= p2Pts + 2 {
            winner = .player1
            isComplete = true
        } else if p2Pts >= 4 && p2Pts >= p1Pts + 2 {
            winner = .player2
            isComplete = true
        }
        // Deuce/Adv handled by scoreDisplay, no end condition met yet
    }

    func reset() {
        points = [.player1: 0, .player2: 0]
        winner = nil
        isComplete = false
    }
}

// Represents the state of a single set
class TennisSet: ObservableObject {
    @Published private(set) var games: [PlayerID: Int] = [.player1: 0, .player2: 0]
    @Published var currentGame: Game = Game()
    @Published private(set) var winner: PlayerID? = nil
    @Published private(set) var isComplete: Bool = false
    // Note: Tie-break logic omitted for simplicity

    func addGame(winner gameWinner: PlayerID) {
        guard !isComplete else { return }
        games[gameWinner, default: 0] += 1
        checkSetEnd()
        if !isComplete {
            currentGame.reset() // Start new game
        }
    }

    private func checkSetEnd() {
        guard let p1Games = games[.player1], let p2Games = games[.player2] else { return }
        // Add Tie-break check here (e.g., if 6-6)
        if p1Games >= 6 && p1Games >= p2Games + 2 {
            winner = .player1
            isComplete = true
        } else if p2Games >= 6 && p2Games >= p1Games + 2 {
            winner = .player2
            isComplete = true
        }
    }

    func reset() {
        games = [.player1: 0, .player2: 0]
        currentGame.reset()
        winner = nil
        isComplete = false
    }
}

// Represents the overall match state
class Match: ObservableObject {
    @Published var playerNames: [PlayerID: String] = [.player1: "Player 1", .player2: "Player 2"]
    @Published var sets: [TennisSet] = []
    @Published var currentSetIndex: Int = 0
    @Published private(set) var winner: PlayerID? = nil
    @Published private(set) var isComplete: Bool = false
    @Published var isAdvancedMode: Bool = false
    @Published var pointHistory: [PointRecord] = []

    private let setsToWin = 2 // Best of 3

    init() {
        startNewSet()
    }

    var currentSet: TennisSet? {
        guard sets.indices.contains(currentSetIndex) else { return nil }
        return sets[currentSetIndex]
    }

    var setsWon: [PlayerID: Int] {
        var counts: [PlayerID: Int] = [.player1: 0, .player2: 0]
        for set in sets where set.isComplete {
            if let setWinner = set.winner {
                counts[setWinner, default: 0] += 1
            }
        }
        return counts
    }

    func addPoint(for player: PlayerID, outcome: PointOutcome?) {
        guard !isComplete, let currentSet = currentSet else { return }

        // Record point
        let record = PointRecord(winningPlayer: player, outcome: isAdvancedMode ? outcome : nil)
        pointHistory.append(record)

        // Add point to current game
        currentSet.currentGame.addPoint(for: player)

        // Check game end
        if currentSet.currentGame.isComplete, let gameWinner = currentSet.currentGame.winner {
            currentSet.addGame(winner: gameWinner)

            // Check set end
            if currentSet.isComplete {
                 // Check match end
                if setsWon[.player1] == setsToWin {
                    winner = .player1
                    isComplete = true
                } else if setsWon[.player2] == setsToWin {
                    winner = .player2
                    isComplete = true
                } else if sets.count < 3 { // Ensure we don't exceed 3 sets
                    startNewSet()
                } else {
                    // Should technically be over if setsToWin met, or handle 3rd set completion
                    isComplete = true // Or determine winner based on 3rd set if needed
                }
            }
        }
    }

    private func startNewSet() {
        guard sets.count < 3 else { return } // Max 3 sets
        let newSet = TennisSet()
        sets.append(newSet)
        currentSetIndex = sets.count - 1
    }

    func resetMatch() {
        sets.removeAll()
        currentSetIndex = 0
        winner = nil
        isComplete = false
        isAdvancedMode = false
        pointHistory.removeAll()
        startNewSet()
    }
}

