```swift
import Foundation
import AVFoundation
import Combine // For Timer publisher
import SwiftUI // For CGFloat

@MainActor // Ensure UI updates happen on the main thread
class AudioRecorderViewModel: ObservableObject {
    @Published var isRecording = false
    @Published var audioLevel: CGFloat = 0.0 // Normalized level 0.0 to 1.0 for UI
    @Published var hasMicrophoneAccess = false
    @Published var displayPermissionError = false
    @Published var displayGenericError = false
    @Published var errorMessage = ""
    @Published var savedRecordingURL: URL? = nil

    private var audioRecorder: AVAudioRecorder?
    private let audioSession: AVAudioSession = AVAudioSession.sharedInstance()
    private var meterTimerCancellable: AnyCancellable?

    init() {
        checkMicrophonePermission()
    }

    // --- Public Methods ---

    func checkMicrophonePermission() {
        switch audioSession.recordPermission {
        case .granted:
            hasMicrophoneAccess = true
            setupAudioSession() // Setup session if permission already granted
        case .denied:
            hasMicrophoneAccess = false
            displayPermissionError = true
            errorMessage = "Microphone access was denied. Please enable it in Settings."
        case .undetermined:
            hasMicrophoneAccess = false
            requestMicrophonePermission()
        @unknown default:
            hasMicrophoneAccess = false
            errorMessage = "Unknown microphone permission state."
            displayGenericError = true
        }
    }

    func startRecording() {
        guard hasMicrophoneAccess else {
            errorMessage = "Cannot start recording without microphone permission."
            displayPermissionError = true // Show permission error specifically
            return
        }

        guard !isRecording else { return } // Don't start if already recording

        // Define file path in Documents directory
        let documentPath = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        let audioFilename = documentPath.appendingPathComponent("\(UUID().uuidString).m4a")
        savedRecordingURL = nil // Clear previous URL

        let settings = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
            AVSampleRateKey: 12000, // Lower sample rate for voice is often sufficient
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.medium.rawValue // Medium quality is often fine for voice
        ]

        do {
            // Ensure session is active *before* initializing recorder
            try audioSession.setActive(true)

            audioRecorder = try AVAudioRecorder(url: audioFilename, settings: settings)
            audioRecorder?.isMeteringEnabled = true
            audioRecorder?.prepareToRecord()
            audioRecorder?.record()

            isRecording = true
            startMetering()

        } catch {
            handleError("Could not start recording: \(error.localizedDescription)")
        }
    }

    func stopRecording() {
        guard isRecording else { return }

        audioRecorder?.stop()
        savedRecordingURL = audioRecorder?.url // Store the URL before resetting recorder
        audioRecorder = nil // Release the recorder object
        stopMetering()
        isRecording = false
        audioLevel = 0.0 // Reset level visually

        // Deactivate session after stopping
        do {
            try audioSession.setActive(false, options: .notifyOthersOnDeactivation)
        } catch {
           print("Warning: Failed to deactivate audio session: \(error.localizedDescription)")
           // Non-fatal, just log for debugging
        }
    }

    // --- Private Helper Methods ---

    private func requestMicrophonePermission() {
        audioSession.requestRecordPermission { [weak self] granted in
             Task { @MainActor [weak self] in // Ensure update happens on main thread
                 self?.hasMicrophoneAccess = granted
                 if granted {
                     self?.setupAudioSession()
                 } else {
                     self?.errorMessage = "Microphone access was denied. Please enable it in Settings."
                     self?.displayPermissionError = true
                 }
             }
        }
    }

    private func setupAudioSession() {
        do {
            try audioSession.setCategory(.playAndRecord, mode: .default, options: [.duckOthers, .defaultToSpeaker])
            // Session will be activated just before recording starts
        } catch {
            handleError("Failed to set up audio session: \(error.localizedDescription)")
        }
    }

    private func startMetering() {
        meterTimerCancellable = Timer.publish(every: 0.05, on: .main, in: .common) // More frequent updates
            .autoconnect()
            .sink { [weak self] _ in
                guard let self = self, let recorder = self.audioRecorder, self.isRecording else { return }
                recorder.updateMeters()
                // Power ranges from -160 (silence) to 0 (max).
                let power = recorder.averagePower(forChannel: 0)
                // Normalize power to 0.0 - 1.0. Using -50dB as a practical 'silence' floor.
                let level = CGFloat(max(0.0, min(1.0, (power + 50) / 50)))
                self.audioLevel = level
            }
    }

    private func stopMetering() {
        meterTimerCancellable?.cancel()
        meterTimerCancellable = nil
    }

    private func handleError(_ message: String) {
         print("Error: \(message)") // Log for debugging
         errorMessage = message
         displayGenericError = true // Show generic error alert
         // Reset state if appropriate
         isRecording = false
         stopMetering()
    }

    deinit {
        stopMetering() // Ensure timer is cancelled
        if isRecording {
            stopRecording() // Ensure recording stops if VM deinitializes
        }
    }
}
