```swift
import SwiftUI

struct EqualizerView: View {
    let level: CGFloat // Normalized level (0.0 to 1.0)
    let numberOfBars: Int = 7 // Odd number looks nice sometimes

    var body: some View {
        HStack(spacing: 5) {
            ForEach(0..<numberOfBars, id: \.self) { index in
                let barLevel = calculateBarLevel(for: index)
                let barHeight = max(5, barLevel * 100) // Base height * level, min height 5

                RoundedRectangle(cornerRadius: 3)
                    .fill(level > 0.05 ? Color.green : Color.gray.opacity(0.4)) // Active vs inactive color
                    .frame(width: 8, height: barHeight)
                    .animation(.easeOut(duration: 0.08), value: barHeight) // Smooth animation
            }
        }
        .frame(height: 120) // Container height
        .opacity(level > 0 ? 1.0 : 0.5) // Dim slightly when silent
    }

    // Add some variation based on bar index for a more dynamic look
    private func calculateBarLevel(for index: Int) -> CGFloat {
        let centerIndex = CGFloat(numberOfBars / 2)
        let distanceFromCenter = abs(CGFloat(index) - centerIndex)
        // Bars closer to the center are generally higher
        let varianceFactor = 1.0 - (distanceFromCenter / (centerIndex + 1.0)) * 0.4 // Reduce height slightly for outer bars
        let randomFactor = CGFloat.random(in: 0.85...1.0) // Add slight randomness
        return level * varianceFactor * randomFactor
    }
}

