// MARK: - Audio Manager (Service Layer)

/// Manages audio recording operations using AVFoundation.
class AudioRecorderService: NSObject, AVAudioRecorderDelegate {
    private var audioSession: AVAudioSession
    private var audioRecorder: AVAudioRecorder?
    private var recordingURL: URL?

    /// A closure that is called periodically with the average power level during recording.
    var audioLevelUpdateHandler: ((Float) -> Void)?

    /// A closure that is called when recording finishes or fails.
    var recordingDidFinishHandler: ((Result<URL, Error>) -> Void)?

    override init() {
        self.audioSession = AVAudioSession.sharedInstance()
        super.init()
    }

    /// Requests microphone permission from the user.
    func requestPermission(completion: @escaping (Bool) -> Void) {
        switch audioSession.recordPermission {
        case .granted:
            completion(true)
        case .denied:
            completion(false)
        case .undetermined:
            audioSession.requestRecordPermission { granted in
                DispatchQueue.main.async {
                    completion(granted)
                }
            }
        @unknown default:
            completion(false)
        }
    }

    /// Starts the audio recording process.
    func startRecording() {
        requestPermission { [weak self] granted in
            guard let self = self, granted else {
                // Consider propagating a specific permission error
                self?.recordingDidFinishHandler?(.failure(RecordingError.permissionDenied))
                print("Error: Microphone permission denied.")
                return
            }

            do {
                // Configure the audio session for recording.
                try self.audioSession.setCategory(.playAndRecord, mode: .default)
                try self.audioSession.setActive(true)

                // Define recording settings.
                let settings: [String: Any] = [
                    AVFormatIDKey: Int(kAudioFormatMPEG4AAC), // AAC format
                    AVSampleRateKey: 44100.0,                // Standard sample rate
                    AVNumberOfChannelsKey: 1,                 // Mono channel
                    AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue // High quality
                ]

                // Create a unique URL in the app's documents directory.
                let documentsPath = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
                self.recordingURL = documentsPath.appendingPathComponent("\(UUID().uuidString).m4a")

                guard let url = self.recordingURL else {
                    self.recordingDidFinishHandler?(.failure(RecordingError.fileCreationFailed))
                    return
                }

                // Initialize the audio recorder.
                self.audioRecorder = try AVAudioRecorder(url: url, settings: settings)
                self.audioRecorder?.delegate = self
                self.audioRecorder?.isMeteringEnabled = true // Enable audio level metering

                // Start recording.
                if self.audioRecorder?.prepareToRecord() == true {
                    self.audioRecorder?.record()
                    print("Recording started successfully.")
                } else {
                    self.recordingDidFinishHandler?(.failure(RecordingError.recorderSetupFailed))
                    print("Error: Failed to prepare audio recorder.")
                }

            } catch {
                self.recordingDidFinishHandler?(.failure(error))
                print("Error setting up audio recording: \(error.localizedDescription)")
            }
        }
    }

    /// Stops the audio recording process.
    func stopRecording() {
        guard let recorder = audioRecorder, recorder.isRecording else {
            print("Warning: stopRecording called but recorder is not active.")
            // If it wasn't recording, maybe it failed earlier. Ensure handler is called.
            if let url = recordingURL {
                // If a file URL exists but recording didn't start/failed early, report failure.
                 recordingDidFinishHandler?(.failure(RecordingError.recordingNotStartedOrFailed))
            }
            cleanupAfterRecording()
            return
        }
        print("Stopping recording.")
        recorder.stop()
        // The actual finalization and success/failure reporting happens in the delegate method audioRecorderDidFinishRecording.
    }

    /// Updates the audio level handler with the current average power.
    func updateMeters() {
        guard let recorder = audioRecorder, recorder.isRecording else { return }
        recorder.updateMeters()
        let averagePower = recorder.averagePower(forChannel: 0) // Power in dBFS (-160 to 0)
        audioLevelUpdateHandler?(averagePower)
    }

    /// Cleans up resources after recording stops or fails.
    private func cleanupAfterRecording() {
        audioRecorder = nil
        recordingURL = nil
        // Deactivate audio session (optional, depends on app needs)
        // try? audioSession.setActive(false)
    }

    // MARK: - AVAudioRecorderDelegate

    func audioRecorderDidFinishRecording(_ recorder: AVAudioRecorder, successfully flag: Bool) {
        print("audioRecorderDidFinishRecording called. Success: \(flag)")
        if flag, let url = recordingURL {
            recordingDidFinishHandler?(.success(url))
        } else {
            // Use the recorder's error if available, otherwise a generic error
            let error = recorder.error ?? RecordingError.recordingFailedUnknown
             recordingDidFinishHandler?(.failure(error))
        }
        cleanupAfterRecording()
    }

    func audioRecorderEncodeErrorDidOccur(_ recorder: AVAudioRecorder, error: Error?) {
        print("Audio recorder encode error: \(error?.localizedDescription ?? "Unknown error")")
        recordingDidFinishHandler?(.failure(error ?? RecordingError.encodingFailed))
        cleanupAfterRecording()
    }
}

/// Custom errors for recording failures.
enum RecordingError: Error, LocalizedError {
    case permissionDenied
    case fileCreationFailed
    case recorderSetupFailed
    case recordingNotStartedOrFailed
    case recordingFailedUnknown
    case encodingFailed

    var errorDescription: String? {
