        case .fileCreationFailed: return "Could not create the audio file."
        case .recorderSetupFailed: return "Failed to set up the audio recorder."
        case .recordingNotStartedOrFailed: return "Recording was not started or failed previously."
        case .recordingFailedUnknown: return "Recording failed for an unknown reason."
