struct Node {
    // Use std::array instead of std::vector
    std::array<Node*, 26> children;
    int cnt;

    Node() : cnt(0) {
        // Initialize all pointers to nullptr
        children.fill(nullptr);
    }

    // Add a destructor to free allocated children (important for memory management)
    ~Node() {
        for (Node* child : children) {
            delete child; // Recursively deletes children
        }
    }
};

class Trie {
public:
    Trie() {
        root = new Node();
    }

    // Add a destructor for the Trie class
    ~Trie() {
        delete root; // This will trigger the recursive deletion in Node's destructor
    }

    // Make Trie non-copyable and non-movable to prevent shallow copies
    // Or implement proper copy/move semantics if needed
    Trie(const Trie&) = delete;
    Trie& operator=(const Trie&) = delete;
    Trie(Trie&&) = delete;
    Trie& operator=(Trie&&) = delete;


    void insert(const std::string& s) {
        Node* current = root;
        for (char ch : s) {
            int index = ch - 'a';
            if (current->children[index] == nullptr) {
                current->children[index] = new Node();
            }
            current = current->children[index];
            current->cnt++; // Increment count of the node representing the prefix ending here
        }
    }

    int queryPrefix(const std::string& s) {
        int scoreSum = 0;
        Node* current = root;
        for (char ch : s) {
            int index = ch - 'a';
            // Check if path exists
            if (current->children[index] == nullptr) {
                // Prefix does not exist fully in the trie
                // The sum should stop here as per the problem's definition.
                break;
            }
            current = current->children[index];
            scoreSum += current->cnt; // Add the count of the node corresponding to the current prefix
        }
        return scoreSum;
    }

private:
    Node* root;

    // Original recursive functions are no longer needed with the iterative approach
    // Kept iterative approach as it's often slightly more efficient and avoids stack depth issues
};

// Solution class remains the same, but ensure const correctness is used
class Solution {
public:
    std::vector<int> sumPrefixScores(const std::vector<std::string>& words) { // Add const&
        Trie trie;
        for (const std::string& s : words) { // Add const&
            trie.insert(s);
        }
        std::vector<int> answer;
        answer.reserve(words.size()); // Reserve space for efficiency
        for (const std::string& s : words) { // Add const&
            answer.push_back(trie.queryPrefix(s));
        }
        return answer;
    }
};

