class Trie {
public:
    Trie() : root(std::make_unique<Node>()) {} // Initialize root with unique_ptr

    void insert(const std::string& s) {
        Node* current = root.get();
        for (char ch : s) {
            int index = ch - 'a';
            if (current->children[index] == nullptr) {
                current->children[index] = std::make_unique<Node>();
            }
            current = current->children[index].get();
            current->cnt++; // Increment count of the node we move *into*
        }
    }

    int queryPrefix(const std::string& s) {
        int score_sum = 0;
        Node* current = root.get();
        for (char ch : s) {
            int index = ch - 'a';
            if (current->children[index] == nullptr) {
                // Prefix doesn't fully exist in the trie
                return score_sum; // Return sum collected so far
            }
            current = current->children[index].get();
            score_sum += current->cnt; // Add the count of the node representing the current prefix
        }
        return score_sum;
    }

private:
    std::unique_ptr<Node> root; // Use smart pointer for root

    // Note: The original recursive functions can also be adapted, but iteration
