                highlightedCode = highlightedCode.replace(/`([^`]+)`/g, '<span class="token-string">`$1`</span>'); // Inline code
                highlightedCode = highlightedCode.replace(/^```(\w*\n)?([\s\S]*?)^```/gm, (match, lang, code) => `<pre class="token-comment"><code>${escapeHtml(code)}</code></pre>`); // Code blocks
            }

            // Add trailing newline if original code had one, helps with scrolling sync
            if (code.endsWith('\n')) {
                highlightedCode += '\n';
            }

            return highlightedCode;
        }

        languageSelect.addEventListener('change', () => {
            updateEditor();
            localStorage.setItem('advancedNotepadLang', languageSelect.value);
        });

        // --- Auto Indent ---
        editor.addEventListener('keydown', (e) => {
            if (e.key === 'Tab') {
                e.preventDefault();
                const start = editor.selectionStart;
                const end = editor.selectionEnd;
                const text = editor.value;
                editor.value = text.substring(0, start) + '    ' + text.substring(end); // Insert 4 spaces
                editor.selectionStart = editor.selectionEnd = start + 4;
                updateEditor();
            } else if (e.key === 'Enter') {
                e.preventDefault();
                const start = editor.selectionStart;
                const end = editor.selectionEnd;
                const text = editor.value;
                const currentLineStart = text.lastIndexOf('\n', start - 1) + 1;
                const currentLine = text.substring(currentLineStart, start);
                const indentMatch = currentLine.match(/^\s*/);
                const indent = indentMatch ? indentMatch[0] : '';

                // Basic bracket handling: increase indent if line ends with { or [
                let extraIndent = '';
                if (/[\{\[]\s*$/.test(currentLine)) {
                     extraIndent = '    '; // Add one level of indentation
                }

                 // Handle closing bracket: decrease indent if typing '}' or ']' on a new line
                let newCursorPos = start + indent.length + extraIndent.length + 1;
                let textToInsert = '\n' + indent + extraIndent;

                // Smart dedent: If the character *after* the cursor is '}' or ']', and the current line is only whitespace
                 if (/^\s*[\}\]]$/.test(text.substring(start))) {
                    const prevIndentMatch = indent.match(/^(\s{4,}|\s*\t)/); // Check if indented at least one level
                    if (prevIndentMatch && indent.length >= 4) {
                        const shorterIndent = indent.substring(0, indent.length - 4);
                         textToInsert = '\n' + shorterIndent;
                         newCursorPos = start + shorterIndent.length + 1;
                    }
                 }


                editor.value = text.substring(0, start) + textToInsert + text.substring(end);
                editor.selectionStart = editor.selectionEnd = newCursorPos;
                updateEditor();
            } else if ((e.ctrlKey || e.metaKey) && e.key === 's') {
                 e.preventDefault();
                 saveFile();
            } else if ((e.ctrlKey || e.metaKey) && e.key === 'o') {
                 e.preventDefault();
                 openFile();
            } else if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
                 e.preventDefault();
                 toggleFindReplacePanel();
                 findInput.focus();
                 findInput.select();
            } else if (e.key === 'Escape') {
                 if(findReplacePanel.style.display === 'block') {
                     toggleFindReplacePanel();
                 }
            }
        });

        // --- File Operations ---
        function updateTitle() {
            document.title = `Advanced Notepad ${isDirty ? '*' : ''}`;
        }

        function newFile() {
            if (isDirty && !confirm("Discard unsaved changes and start a new file?")) {
                return;
            }
            editor.value = '';
            currentFilePath = null;
            isDirty = false;
            languageSelect.value = 'plaintext';
            updateEditor();
            updateTitle();
        }
        document.getElementById('btn-new').addEventListener('click', newFile);

        function openFile() {
             if (isDirty && !confirm("Discard unsaved changes before opening a new file?")) {
                return;
            }
            fileInput.click();
        }
        document.getElementById('btn-open').addEventListener('click', openFile);

        fileInput.addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = (event) => {
                editor.value = event.target.result;
                currentFilePath = file.name; // Store filename
                isDirty = false;
                // Try to guess language from extension
                const ext = file.name.split('.').pop().toLowerCase();
                const langMap = { js: 'javascript', html: 'html', htm: 'html', css: 'css', json: 'json', md: 'markdown' };
                languageSelect.value = langMap[ext] || 'plaintext';
                updateEditor();
                updateTitle();
                fileInput.value = null; // Reset file input
            };
            reader.onerror = () => {
                alert('Error reading file.');
                fileInput.value = null; // Reset file input
            };
            reader.readAsText(file);
        });

        function saveFile() {
            const content = editor.value;
            const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            // Use current filename or default
            a.download = currentFilePath || 'untitled.txt';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            isDirty = false;
            updateTitle();
             updateStatusBar(editor.value); // Update status bar to remove "(Unsaved)"
        }
        document.getElementById('btn-save').addEventListener('click', saveFile);


        // --- Theme Toggle ---
        function toggleTheme() {
            document.body.classList.toggle('dark-theme');
             localStorage.setItem('advancedNotepadTheme', document.body.classList.contains('dark-theme') ? 'dark' : 'light');
        }
        document.getElementById('btn-theme').addEventListener('click', toggleTheme);

         // --- Word Wrap Toggle ---
        function toggleWordWrap() {
            wordWrap = !wordWrap;
            if (wordWrap) {
                editor.style.whiteSpace = 'pre-wrap';
                editor.style.overflowWrap = 'break-word';
                highlightingLayer.style.whiteSpace = 'pre-wrap';
                highlightingLayer.style.overflowWrap = 'break-word';
                editor.style.overflowX = 'hidden';
                highlightingLayer.style.overflowX = 'hidden';
            } else {
                editor.style.whiteSpace = 'pre';
                editor.style.overflowWrap = 'normal';
                highlightingLayer.style.whiteSpace = 'pre';
                highlightingLayer.style.overflowWrap = 'normal';
                 editor.style.overflowX = 'auto';
                highlightingLayer.style.overflowX = 'auto';
            }
            // Re-render might be needed if line numbers change visually
            updateEditor();
            document.getElementById('btn-wrap').textContent = wordWrap ? 'Disable Wrap' : 'Enable Wrap';
        }
        document.getElementById('btn-wrap').addEventListener('click', toggleWordWrap);

        // --- Find/Replace ---
        function toggleFindReplacePanel() {
            const isVisible = findReplacePanel.style.display === 'block';
            findReplacePanel.style.display = isVisible ? 'none' : 'block';
            if (!isVisible) {
                findInput.focus();
                findInput.select();
                lastSearch = ''; // Reset search context when opening
                currentFindIndex = -1;
            }
        }
        document.getElementById('btn-find').addEventListener('click', toggleFindReplacePanel);
        document.getElementById('btn-close-find').addEventListener('click', toggleFindReplacePanel);

        function performFind(reverse = false) {
            const searchTerm = findInput.value;
            if (!searchTerm) return;

            const content = editor.value;
            let startIndex;

            if (searchTerm !== lastSearch) {
                // New search term, reset index
                currentFindIndex = -1;
                lastSearch = searchTerm;
            }

            if (reverse) {
                startIndex = (currentFindIndex !== -1) ? currentFindIndex - 1 : editor.selectionStart - 1;
                currentFindIndex = content.lastIndexOf(searchTerm, startIndex);
            } else {
                 startIndex = (currentFindIndex !== -1 && editor.selectionStart > currentFindIndex)
                    ? editor.selectionStart // Start from after current selection if moved
                    : (currentFindIndex !== -1 ? currentFindIndex + 1 : editor.selectionStart); // Start after last match or current cursor

                currentFindIndex = content.indexOf(searchTerm, startIndex);
            }

            if (currentFindIndex !== -1) {
                editor.focus();
                editor.selectionStart = currentFindIndex;
                editor.selectionEnd = currentFindIndex + searchTerm.length;
                // Scroll into view - ensure the editor has focus first
                const tempElement = document.createElement('span');
                editor.parentNode.insertBefore(tempElement, editor); // Helper for scrolling logic if needed
                editor.scrollIntoView({ block: 'nearest', inline: 'nearest' });
                tempElement.remove();

            } else {
                alert(`'${searchTerm}' not found.`);
                currentFindIndex = -1; // Reset if not found
            }
        }

        document.getElementById('btn-find-next').addEventListener('click', () => performFind(false));
        document.getElementById('btn-find-prev').addEventListener('click', () => performFind(true));
        findInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                performFind(e.shiftKey); // Shift+Enter for previous
            }
         });

        function performReplace() {
            const searchTerm = findInput.value;
            const replaceTerm = replaceInput.value;
            if (!searchTerm) return;

            if (editor.selectionStart === currentFindIndex && editor.selectionEnd === currentFindIndex + searchTerm.length && editor.value.substring(editor.selectionStart, editor.selectionEnd) === searchTerm) {
                 const start = editor.selectionStart;
                 editor.setRangeText(replaceTerm, start, editor.selectionEnd, 'select');
                 // Move selection to end of replaced text
                 editor.selectionStart = editor.selectionEnd;
                 currentFindIndex = start; // Update index for next find
                 updateEditor();
                 performFind(false); // Automatically find next after replacing
             } else {
                 // If selection doesn't match, just find the next occurrence
                 performFind(false);
             }
        }
        document.getElementById('btn-replace').addEventListener('click', performReplace);

        function performReplaceAll() {
            const searchTerm = findInput.value;
            const replaceTerm = replaceInput.value;
            if (!searchTerm) return;

            const originalScrollTop = editor.scrollTop;
            const originalScrollLeft = editor.scrollLeft;
            editor.value = editor.value.split(searchTerm).join(replaceTerm); // Simple replace all
            editor.scrollTop = originalScrollTop; // Restore scroll position
            editor.scrollLeft = originalScrollLeft;
            currentFindIndex = -1; // Reset find index
            updateEditor();
        }
        document.getElementById('btn-replace-all').addEventListener('click', performReplaceAll);


        // --- Initialization ---
        function initialize() {
            // Load theme preference
            const savedTheme = localStorage.getItem('advancedNotepadTheme');
            if (savedTheme === 'dark') {
                document.body.classList.add('dark-theme');
            }

             // Load last content and language
            const savedContent = localStorage.getItem('advancedNotepadContent');
            const savedLang = localStorage.getItem('advancedNotepadLang');
            if (savedContent) {
                editor.value = savedContent;
            }
             if (savedLang) {
                 languageSelect.value = savedLang;
             }

            updateEditor();
            isDirty = false; // Initial load is not dirty
            updateTitle();
            editor.focus(); // Focus editor on load
        }

        initialize();

    </script>
</body>
