        // --- Syntax Highlighting ---

        function escapeHtml(text) {
            return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        }

        function highlightSyntax(code, language) {
            let escapedCode = escapeHtml(code);
            switch (language) {
                case 'javascript':
                case 'json': // Treat JSON similar to JS for basic highlighting
                    // Comments (// and /* */)
                    escapedCode = escapedCode.replace(/(\/\/.*$)|(\/\*[\s\S]*?\*\/)/gm, '<span class="token-comment">$1$2</span>');
                    // Strings ("", '', ``) - basic handling
                    escapedCode = escapedCode.replace(/("(?:\\.|[^"\\])*")|('(?:\\.|[^'\\])*')|(`(?:\\.|[^`\\])*`)/g, '<span class="token-string">$1$2$3</span>');
                     // Keywords (add more as needed)
                    const jsKeywords = ['const', 'let', 'var', 'function', 'if', 'else', 'for', 'while', 'return', 'class', 'import', 'export', 'try', 'catch', 'null', 'undefined', 'new', 'this', 'async', 'await', 'switch', 'case', 'default', 'break', 'continue'];
                    escapedCode = escapedCode.replace(new RegExp(`\\b(${jsKeywords.join('|')})\\b`, 'g'), '<span class="token-keyword">$1</span>');
                    // Boolean
                    escapedCode = escapedCode.replace(/\b(true|false)\b/g, '<span class="token-boolean">$1</span>');
                    // Numbers
                    escapedCode = escapedCode.replace(/\b(\d+(\.\d+)?)\b/g, '<span class="token-number">$1</span>');
                    break;
                case 'html':
                     // Comments
                    escapedCode = escapedCode.replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span class="token-comment">$1</span>');
                    // Tags and Attributes
                    escapedCode = escapedCode.replace(/(&lt;\/?)([a-zA-Z0-9\-]+)/g, '$1<span class="token-tag">$2</span>'); // Tag names
                    escapedCode = escapedCode.replace(/([a-zA-Z\-]+)=(".*?"|'.*?')/g, '<span class="token-attr-name">$1</span>=<span class="token-attr-value">$2</span>'); // Attributes
                    escapedCode = escapedCode.replace(/(&gt;)/g, '<span class="token-tag">$1</span>'); // Closing bracket
                    break;
                case 'css':
                    // Comments
                    escapedCode = escapedCode.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="token-comment">$1</span>');
                    // Strings
                    escapedCode = escapedCode.replace(/("(?:\\.|[^"\\])*")|('(?:\\.|[^'\\])*')/g, '<span class="token-string">$1$2</span>');
                    // Selectors (basic) & Properties
                     escapedCode = escapedCode.replace(/^([\s]*)([\.#]?[a-zA-Z0-9\-_*:]+[\s\S]*?)(?=\s*\{)/gm, '$1<span class="token-css-selector">$2</span>'); // Selectors
                    escapedCode = escapedCode.replace(/([a-zA-Z\-]+)\s*:/g, '<span class="token-css-property">$1</span>:'); // Properties
                    // Values (numbers, colors, keywords)
                    escapedCode = escapedCode.replace(/:\s*(#[0-9a-fA-F]{3,6}|rgba?\(.+?\)|[a-zA-Z\-]+|\d+(\.\d+)?(px|em|rem|%|vh|vw)?)/g, ': <span class="token-css-value">$1</span>');
