# --- CodeCommit Repository (Assumes you want the pipeline triggered from here) ---
resource "aws_codecommit_repository" "source_repo" {
  repository_name = var.pipeline_source_repo_name
  description     = "Source code repository for ${var.ecs_service_name}"
  tags            = var.tags
}

# --- S3 Bucket for Pipeline Artifacts ---
resource "aws_s3_bucket" "codepipeline_artifacts" {
  bucket = "${lower(var.ecs_service_name)}-pipeline-artifacts-${data.aws_caller_identity.current.account_id}"
  acl    = "private"
  tags   = var.tags

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# --- CodeBuild Project (to force ECS service redeployment) ---
resource "aws_codebuild_project" "deploy_project" {
  name          = "${var.ecs_service_name}-deploy"
  description   = "CodeBuild project to force redeploy ${var.ecs_service_name}"
  service_role  = aws_iam_role.codebuild_role.arn
  build_timeout = "10" # minutes
  tags          = var.tags

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:5.0" # Use a standard image with AWS CLI
    type                        = "LINUX_CONTAINER"
    privileged_mode             = false
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "CLUSTER_NAME"
      value = local.ecs_cluster_name # Use the name determined in main.tf
    }
    environment_variable {
      name  = "SERVICE_NAME"
      value = aws_ecs_service.this.name
    }
    environment_variable {
      name  = "AWS_REGION"
      value = var.aws_region
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = <<-EOF
      version: 0.2
      phases:
        build:
          commands:
            - echo "Forcing new deployment for service $SERVICE_NAME in cluster $CLUSTER_NAME..."
            - aws ecs update-service --cluster "$CLUSTER_NAME" --service "$SERVICE_NAME" --force-new-deployment --region "$AWS_REGION"
            - echo "Deployment triggered."
    EOF
  }
}

# --- CodePipeline ---
resource "aws_codepipeline" "pipeline" {
  name     = "${var.ecs_service_name}-pipeline"
  role_arn = aws_iam_role.codepipeline_role.arn
  tags     = var.tags

  artifact_store {
    location = aws_s3_bucket.codepipeline_artifacts.bucket
    type     = "S3"
  }

  stage {
    name = "Source"
    action {
      name             = "Source"
      category         = "Source"
      owner            = "AWS"
      provider         = "CodeCommit"
      version          = "1"
      output_artifacts = ["SourceOutput"]

      configuration = {
        RepositoryName = aws_codecommit_repository.source_repo.repository_name
        BranchName     = var.pipeline_source_branch_name
        PollForSourceChanges = true
      }
    }
  }

  stage {
    name = "Deploy"
    action {
      name            = "ForceRedeploy"
      category        = "Build" # Using Build category for CodeBuild action
      owner           = "AWS"
      provider        = "CodeBuild"
      input_artifacts = ["SourceOutput"] # Needs an input, even if not used by buildspec
      version         = "1"

      configuration = {
        ProjectName = aws_codebuild_project.deploy_project.name
      }
    }
  }
}
