data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_ssm_parameter" "cloudflare_token" {
  # Ensure the name doesn't start with / if SSM parameter name variable already has it
  name = var.cloudflare_token_ssm_parameter_name
}

# --- ECS Cluster ---
resource "aws_ecs_cluster" "this" {
  count = var.create_ecs_cluster ? 1 : 0
  name  = var.ecs_cluster_name
  tags  = var.tags

  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}

# Determine cluster ARN or name based on creation choice
locals {
  ecs_cluster_arn  = var.create_ecs_cluster ? aws_ecs_cluster.this[0].arn : var.existing_ecs_cluster_arn
  ecs_cluster_name = var.ecs_cluster_name # Used by CodeBuild which needs name, not ARN
}

# --- ECS Task Definition ---
resource "aws_ecs_task_definition" "this" {
  family                   = "${var.ecs_service_name}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = var.ecs_task_cpu
  memory                   = var.ecs_task_memory
  execution_role_arn       = aws_iam_role.ecs_task_execution_role.arn
  # task_role_arn          = Optional: Add if the container needs permissions to call AWS APIs
  tags                     = var.tags

  container_definitions = jsonencode([
    {
      name      = var.ecs_service_name # Container name
      image     = var.ecr_image_uri
      cpu       = var.ecs_task_cpu     # You can define CPU/Memory per container or at task level
      memory    = var.ecs_task_memory
      essential = true
      # Add port mappings if Warp needs to expose a port (unlikely for client usage)
      # portMappings = [
      #   {
      #     containerPort = 8080 # Example port
      #     hostPort      = 8080 # Example port
      #     protocol      = "tcp"
      #   }
      # ]
      secrets = [
        {
          name      = "CLOUDFLARE_TOKEN" # The environment variable name inside the container
          valueFrom = data.aws_ssm_parameter.cloudflare_token.arn # Use the ARN for secrets
        }
      ]
      logConfiguration = { # Recommended for visibility
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = "/ecs/${var.ecs_service_name}"
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])
}

# --- CloudWatch Log Group for Task Logs ---
resource "aws_cloudwatch_log_group" "task_logs" {
  name = "/ecs/${var.ecs_service_name}"
  tags = var.tags
}

# --- ECS Service ---
resource "aws_ecs_service" "this" {
  name            = var.ecs_service_name
  cluster         = local.ecs_cluster_arn
  task_definition = aws_ecs_task_definition.this.arn
  desired_count   = var.ecs_task_desired_count
  launch_type     = "FARGATE"

  # Ensure deployment controller waits for CodeDeploy/CodeBuild if used more complexly
  # deployment_controller {
  #   type = "ECS" # Use CODE_DEPLOY if using that deployment strategy
  # }

  network_configuration {
    subnets          = var.vpc_subnets
    security_groups  = var.vpc_security_group_ids
    assign_public_ip = var.assign_public_ip
  }

  # Optional: Configure service discovery, load balancing, etc. here

  lifecycle {
    ignore_changes = [task_definition, desired_count] # Allow CodePipeline/external tools to manage these
  }

  depends_on = [
    aws_cloudwatch_log_group.task_logs,
    aws_iam_role_policy.ecs_task_execution_policy # Ensure role policy is attached before service creation
  ]

  tags = var.tags
}
