export type Result<T, E = unknown> =
  | { success: true; value: T }
  | { success: false; error: E };

/**
 * Wraps a synchronous function call in a try/catch block.
 *
 * @template T The expected type of the successful result.
 * @param fn The synchronous function to execute.
 * @returns A Result object indicating success (with the value) or failure (with the error).
 *          The error type in the Result is 'unknown' as caught errors are of this type.
 */
export function tryCatch<T>(fn: () => T): Result<T, unknown> {
  try {
    const value = fn();
    return { success: true, value: value };
  } catch (error) {
    return { success: false, error: error };
  }
}

