// Disjoint Set Union (DSU) structure to manage connected components
struct DSU {
    std::vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        // Initialize each node as its own parent (representing separate components)
        std::iota(parent.begin(), parent.end(), 0); 
    }

    // Find the representative (root) of the set containing element i, with path compression
    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]); // Path compression
    }

    // Unite the sets containing elements i and j, by rank or size (here simple union)
    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            // Make root_i the parent of root_j (or vice versa)
            parent[root_j] = root_i; 
        }
    }
};

