/* server.c */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h> // Include for int16_t
#include <arpa/inet.h>
#include <sys/socket.h>
#include <libevdev/libevdev.h>
#include <libevdev/libevdev-uinput.h>
#include <unistd.h>
#include <linux/input.h> // Include for EV_* constants

#define BUFFER_SIZE 512 // Ensure buffer is large enough (18 pairs * 4 bytes/pair = 72 bytes)
#define PORT 31415

struct controller_event {
    unsigned int type;
    unsigned int code;
    const char *name;
};

static const struct controller_event REGISTERED_EVENTS[] = {
    {.type=EV_ABS, .code=ABS_X, .name="ANALOG_LX"}, {.type=EV_ABS, .code=ABS_Y, .name="ANALOG_LY"},
    {.type=EV_ABS, .code=ABS_RX, .name="ANALOG_RX"}, {.type=EV_ABS, .code=ABS_RY, .name="ANALOG_RY"},
    {.type=EV_KEY, .code=BTN_TL, .name="L1"}, {.type=EV_KEY, .code=BTN_TL2, .name="L2"},
    {.type=EV_KEY, .code=BTN_TR, .name="R1"}, {.type=EV_KEY, .code=BTN_TR2, .name="R2"},
    {.type=EV_KEY, .code=BTN_NORTH, .name="TRIANGLE"}, {.type=EV_KEY, .code=BTN_SOUTH, .name="CROSS"},
    {.type=EV_KEY, .code=BTN_WEST, .name="SQUARE"}, {.type=EV_KEY, .code=BTN_EAST, .name="CIRCLE"},
    {.type=EV_KEY, .code=BTN_DPAD_UP, .name="UP"}, {.type=EV_KEY, .code=BTN_DPAD_DOWN, .name="DOWN"},
    {.type=EV_KEY, .code=BTN_DPAD_LEFT, .name="LEFT"}, {.type=EV_KEY, .code=BTN_DPAD_RIGHT, .name="RIGHT"},
    {.type=EV_KEY, .code=BTN_SELECT, .name="SELECT"}, {.type=EV_KEY, .code=BTN_START, .name="START"},
};

// Calculate the number of registered events
#define EVENT_COUNT (sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0]))

// Define the structure for the event data received from the client {index, value}
struct event_pair {
    int16_t index;
    int16_t value;
};

static struct libevdev_uinput *controller = NULL;

// controller_create function remains largely the same, using EVENT_COUNT
static struct libevdev_uinput *controller_create(void) {
    struct libevdev *device = libevdev_new();
    libevdev_set_name(device, "Virtual Game Controller");

    struct input_absinfo absinfo = {
        .value = 0, .minimum = -32767, .maximum = 32767, .flat = 0, .fuzz = 0, .resolution = 0
    };

    for (int i = 0; i < EVENT_COUNT; ++i) {
        libevdev_enable_event_code(device, REGISTERED_EVENTS[i].type, REGISTERED_EVENTS[i].code,
            (REGISTERED_EVENTS[i].type == EV_ABS) ? &absinfo : NULL);
    }

    struct libevdev_uinput *ui;
    if (libevdev_uinput_create_from_device(device, LIBEVDEV_UINPUT_OPEN_MANAGED, &ui) < 0) {
        fprintf(stderr, "Failed to create uinput device\n");
        exit(EXIT_FAILURE);
    }

    libevdev_free(device);
    return ui;
}


static void udp_server(void) {
    int sockfd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t cli_len = sizeof(cli_addr);
    char buffer[BUFFER_SIZE];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR on binding");
        close(sockfd);
        exit(1);
    }

    printf("UDP Server listening on port %d\n", PORT);

    while (1) {
        ssize_t n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *) &cli_addr, &cli_len);
        if (n < 0) {
            perror("ERROR in recvfrom");
            continue;
        }

        // Check if the received data size is a multiple of the event_pair size
        if (n <= 0 || n % sizeof(struct event_pair) != 0) {
            fprintf(stderr, "Received packet with invalid size: %zd bytes. Expected multiple of %zu bytes.\n", n, sizeof(struct event_pair));
            continue;
        }

        int pair_count = n / sizeof(struct event_pair);
        struct event_pair *pairs = (struct event_pair *)buffer;

        // Process each event pair in the received packet
        for (int i = 0; i < pair_count; ++i) {
            int16_t event_index = pairs[i].index;
            int16_t event_value = pairs[i].value;

            // Validate the event index
            if (event_index >= 0 && event_index < EVENT_COUNT) {
                libevdev_uinput_write_event(controller, REGISTERED_EVENTS[event_index].type,
                                            REGISTERED_EVENTS[event_index].code, event_value);
            } else {
                fprintf(stderr, "Received invalid event index: %d\n", event_index);
                // Optionally break or continue processing other pairs
            }
        }

        // After processing all events in the packet, send a synchronization event
        libevdev_uinput_write_event(controller, EV_SYN, SYN_REPORT, 0);
    }

    close(sockfd); // Unreachable in this loop
}

int main() {
    controller = controller_create();
    udp_server(); // Runs indefinitely
    libevdev_uinput_destroy(controller); // Unreachable
    return 0;
}
```

