```zig
const std = @import("std");
const rl = @import("raylib");
const net = std.net;
const posix = std.posix;
const mem = std.mem;

// Define your controller event indices based on the C server's REGISTERED_EVENTS array
const ControllerEvents = enum(i16) {
    ANALOG_LX = 0, ANALOG_LY = 1, ANALOG_RX = 2, ANALOG_RY = 3,
    L1 = 4, L2 = 5, R1 = 6, R2 = 7,
    TRIANGLE = 8, CROSS = 9, SQUARE = 10, CIRCLE = 11,
    UP = 12, DOWN = 13, LEFT = 14, RIGHT = 15,
    SELECT = 16, START = 17,

    // Helper to get the count of events
    pub const count = @typeInfo(ControllerEvents).Enum.fields.len;
};

// Define the structure for the event data sent to the server {index, value}
const EventPair = extern struct { // Use extern struct for defined layout matching C
    index: i16,
    value: i16,
};

// Define a function to send the entire controller state as an array of EventPairs
fn sendControllerState(sock: posix.fd_t, addr: *const net.Address, eventPairs: []const EventPair) !void {
    const sockaddr = &addr.any;
    const addrlen = addr.getOsSockLen();
    const bytesToSend = mem.sliceAsBytes(eventPairs); // Use sliceAsBytes for []const T
    const totalBytes = bytesToSend.len;

    const ret = try posix.sendto(sock, bytesToSend, 0, sockaddr, addrlen);

    if (@as(usize, @intCast(ret)) != totalBytes) {
        std.log.warn("Warning: Not all data was sent. Expected to send {d} bytes, but sent {d}\n", .{ totalBytes, ret });
    }
}

// Create a UDP socket for sending
fn createUDPSocket() !posix.fd_t {
    const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
    return sock;
}

// Initialize controller state array (stores only values)
fn initializeControllerState() [ControllerEvents.count]i16 {
    var controllerState: [ControllerEvents.count]i16 = undefined;
    @memset(&controllerState, 0); // Set all values to 0
    return controllerState;
}

pub fn main() anyerror!void {
    const alloc = std.heap.page_allocator;

    // Initialization
    const screenWidth = 800;
    const screenHeight = 450;

    rl.initWindow(screenWidth, screenHeight, "raylib-zig example - keyboard to controller input");
    defer rl.closeWindow();

    rl.setTargetFPS(60);

    // Initialize controller state (values only)
    var controllerState = initializeControllerState();

    // Create a UDP socket for sending packets
    const sock = try createUDPSocket();
    defer posix.close(sock);

    // Server address
    const server_addr = try net.Address.parseIp4("127.0.0.1", 31415);

    // Main game loop
    while (!rl.windowShouldClose()) {
        // Update controller state based on keyboard input (example for arrow keys)
        controllerState[@intFromEnum(ControllerEvents.UP)] = if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;
        controllerState[@intFromEnum(ControllerEvents.DOWN)] = if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;
        controllerState[@intFromEnum(ControllerEvents.LEFT)] = if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;
        controllerState[@intFromEnum(ControllerEvents.RIGHT)] = if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;
        // Add mappings for other keys/axes as needed...

        // Prepare the data packet: an array of EventPair structs
        var eventPairs: [ControllerEvents.count]EventPair = undefined;
        inline for (0..ControllerEvents.count) |i| {
            eventPairs[i] = EventPair{
                .index = @intCast(i16, i), // Index from 0 to count-1
                .value = controllerState[i], // Value from the state array
            };
        }

        // Send the current state of the controller to the server
        try sendControllerState(sock, &server_addr, &eventPairs);

        // Draw
        rl.beginDrawing();
        defer rl.endDrawing();
        rl.clearBackground(rl.Color.white);
        rl.drawText("Press arrow keys to simulate controller input!", 190, 200, 20, rl.Color.light_gray);
        // Optional: Display state
        var buf: [100]u8 = undefined;
        const text = try std.fmt.bufPrint(&buf, "UP:{d} DOWN:{d} LEFT:{d} RIGHT:{d}", .{
             controllerState[@intFromEnum(ControllerEvents.UP)],
             controllerState[@intFromEnum(ControllerEvents.DOWN)],
             controllerState[@intFromEnum(ControllerEvents.LEFT)],
             controllerState[@intFromEnum(ControllerEvents.RIGHT)],
        });
         rl.drawText(text, 10, 10, 10, rl.Color.black);
    }
}

