/**
 * Calculates the start and end dates for a sequence of processes
 * based on an initial order creation date and the duration of each process.
 *
 * @param string $orderCreatedDate The initial date/time string (e.g., "25/06/2024 10:45 AM").
 * @param array $processes An array of processes, each containing at least 'sequence' and 'completed_days'.
 *                         The array will be modified in place to add/update 'start_date' and 'end_date'.
 * @param string $dateFormat The format of the input $orderCreatedDate and the desired output date strings.
 *                           Defaults to 'd/m/Y h:i A'.
 * @return array The processed array with calculated 'start_date' and 'end_date' for each process.
 * @throws \InvalidArgumentException If the input date format is invalid.
 * @throws \Exception If Carbon parsing fails.
 */
function calculateProcessDates(string $orderCreatedDate, array &$processes, string $dateFormat = 'd/m/Y h:i A'): array
{
    // Validate and parse the initial order creation date
    try {
        $currentStartDate = Carbon::createFromFormat($dateFormat, $orderCreatedDate);
        if (!$currentStartDate || $currentStartDate->format($dateFormat) !== $orderCreatedDate) {
             throw new \InvalidArgumentException("Invalid date format for orderCreatedDate. Expected format: {$dateFormat}");
        }
    } catch (\InvalidArgumentException $e) {
        // Re-throw with a more specific message or handle as needed
         throw new \InvalidArgumentException("Failed to parse orderCreatedDate '{$orderCreatedDate}' with format '{$dateFormat}'. Ensure the date and format match.");
    }


    // Ensure processes are sorted by sequence for correct calculation order
    usort($processes, function ($a, $b) {
        return ($a['sequence'] ?? 0) <=> ($b['sequence'] ?? 0);
    });

    // Iterate through processes to calculate dates
    foreach ($processes as $key => &$process) {
        if (!isset($process['completed_days']) || !is_numeric($process['completed_days'])) {
            // Handle missing or invalid completed_days - skip, error, or default?
            // For now, let's skip calculation for this process if data is invalid.
            // Alternatively, throw an exception.
            // trigger_error("Process with sequence {$process['sequence']} has invalid 'completed_days'. Skipping date calculation.", E_USER_WARNING);
             $process['start_date'] = 'Invalid Input';
             $process['end_date'] = 'Invalid Input';
             // If we want the chain to stop, we could break or throw here.
             // If subsequent processes should still be calculated based on the *last valid* date,
             // we need to avoid updating $currentStartDate here.
             continue; // Skip to next process
        }

        // Assign the start date (from previous end date or initial order date)
        $process['start_date'] = $currentStartDate->format($dateFormat);

        // Calculate the end date by adding completed_days
        // Use copy() to avoid modifying the $currentStartDate object directly before it's needed for the next iteration
        $endDate = $currentStartDate->copy()->addDays((int)$process['completed_days']);
        $process['end_date'] = $endDate->format($dateFormat);

        // Update $currentStartDate for the next process in the sequence
        $currentStartDate = $endDate;
    }
    // Important: Break the reference binding after the loop
    unset($process);

    return $processes;
}

