<?php

use Carbon\Carbon;
use Illuminate\Support\Collection; // Optional, but can be idiomatic in Laravel

/**
 * Calculates the start and end dates for a series of processes based on an initial date
 * and the duration of each process.
 *
 * @param string $orderCreatedDateString The initial date string (e.g., "25/06/2024 10:45 AM").
 * @param array $processes An array of processes, each containing 'sequence' and 'completed_days'.
 * @param string $dateFormat The format of the input date string and the desired output format (defaults to 'd/m/Y h:i A').
 * @return array The processes array updated with 'start_date' and 'end_date'.
 * @throws \Carbon\Exceptions\InvalidFormatException If the date string format is incorrect.
 */
function calculateProcessDates(string $orderCreatedDateString, array $processes, string $dateFormat = 'd/m/Y h:i A'): array
{
    // 1. Validate and parse the initial date
    try {
        // Use createFromFormat to be explicit about the input format
        $currentDate = Carbon::createFromFormat($dateFormat, $orderCreatedDateString);
    } catch (\Carbon\Exceptions\InvalidFormatException $e) {
        // Handle invalid date format - rethrow, return error, log, etc.
        throw new \InvalidArgumentException("Invalid date format for orderCreatedDateString. Expected format: {$dateFormat}. Error: " . $e->getMessage());
    }

    // 2. Sort processes by sequence
    // Using Collection for a more Laravel-like feel, but usort is fine too.
    $sortedProcesses = collect($processes)->sortBy('sequence')->values()->all();

    // 3. Iterate and calculate dates
    foreach ($sortedProcesses as $index => &$process) { // Use reference '&' to modify the array directly
        if (!isset($process['completed_days']) || !is_numeric($process['completed_days']) || $process['completed_days'] < 0) {
             // Handle missing or invalid completed_days - skip, throw error, default to 0?
             // For now, let's throw an exception for clarity.
             throw new \InvalidArgumentException("Process at index {$index} (sequence {$process['sequence']}) has invalid or missing 'completed_days'.");
        }

        // Set the start date for the current process
        // For the first process, it's the initial date; for others, it's the end date of the previous one.
        // $currentDate already holds the correct start date from the previous iteration or initial setup.
        $process['start_date'] = $currentDate->format($dateFormat);

        // Calculate the end date by adding completed days
        // Use copy() or clone() to avoid modifying the $currentDate object used for the next iteration's start date.
        $endDate = $currentDate->copy()->addDays((int)$process['completed_days']);
        $process['end_date'] = $endDate->format($dateFormat);

        // Update $currentDate to be the end date of the current process, ready for the next iteration
        $currentDate = $endDate;
    }
    // Release the reference
    unset($process);

    // 4. Return the updated array
    return $sortedProcesses;
}

