                float4 texColor = tex2Dlod(_MainTex, float4(input[0].uv, 0, 0));

                // Check if pixel alpha is above the threshold
                if (texColor.a >= _AlphaThreshold)
                {
                    float3 objPos = input[0].objPos.xyz;

                    // Define quad corners relative to the object position
                    // Assuming quads are aligned with XY plane in object space
                    // Use half size for centering
                    float hs = _QuadSize * 0.5;
                    float3 up = float3(0, hs, 0);
                    float3 right = float3(hs, 0, 0);
                    float3 forward = float3(0, 0, _Extrusion); // Extrusion direction (local Z)

                    // Define the 4 base vertices (at z=0 relative to input)
                    float3 v0 = objPos - right - up; // Bottom Left
                    float3 v1 = objPos + right - up; // Bottom Right
                    float3 v2 = objPos - right + up; // Top Left
                    float3 v3 = objPos + right + up; // Top Right

                    // Define the 4 extruded vertices
                    float3 v0_ext = v0 + forward;
                    float3 v1_ext = v1 + forward;
                    float3 v2_ext = v2 + forward;
                    float3 v3_ext = v3 + forward;

                    // Create the output structure
                    g2f o;
                    o.uv = input[0].uv; // Use the original point's UV for the whole quad
                    o.color = texColor;  // Pass the sampled color

                    // --- Generate the extruded quad face ---
                    // Could also generate sides/back for a full box, but keeping simple based on prompt

                    // Triangle 1 (bottom-left, bottom-right, top-right extruded)
                    o.pos = UnityObjectToClipPos(v0_ext); triStream.Append(o);
                    o.pos = UnityObjectToClipPos(v1_ext); triStream.Append(o);
                    o.pos = UnityObjectToClipPos(v3_ext); triStream.Append(o);

                    // Triangle 2 (bottom-left, top-right, top-left extruded)
                    o.pos = UnityObjectToClipPos(v0_ext); triStream.Append(o);
                    o.pos = UnityObjectToClipPos(v3_ext); triStream.Append(o);
                    o.pos = UnityObjectToClipPos(v2_ext); triStream.Append(o);

                    // Alternative Interpretation: Extrude the quad itself, keeping original position
                    // Example: Base at v0,v1,v2,v3; Extruded face at v0_ext, v1_ext, v2_ext, v3_ext
                    // The code above only generates the front (extruded) face.
                    // If a simple offset quad is desired (2 base, 2 extruded):
