    println!("set SO_RCVTIMEO to {:?}", Duration::from_secs(5));
    let time_out = udp_sock.read_timeout()?;
    println!("read SO_RCVTIMEO: {:?}", time_out);
    Ok(())
}
```

**2. 阻止临时 `Socket` 关闭文件描述符 (`into_raw_fd`)**

如果您想保持现有的 `from_raw_fd` 结构，可以在临时 `Socket` 对象被销毁（drop）之前，调用 `into_raw_fd()` 方法。这会消耗掉 `Socket` 对象并返回它所拥有的文件描述符，但关键在于它**不会关闭**该文件描述符，从而将所有权“归还”，避免了原始 `UdpSocket` 的 fd 被关闭。

```rust
use std::os::unix::io::{AsRawFd, FromRawFd, IntoRawFd}; // 需要引入 IntoRawFd
use std::io;
use std::time::Duration;
use socket2::Socket;
use tokio::net::UdpSocket;

pub trait SockOpt {
    fn read_timeout(&self) -> io::Result<Option<Duration>>;
    fn set_read_timeout(&self, duration: Option<Duration>) -> io::Result<()>;
}

impl SockOpt for tokio::net::UdpSocket {
    fn read_timeout(&self) -> io::Result<Option<Duration>> {
        let fd = self.as_raw_fd();
        let sock = unsafe { Socket::from_raw_fd(fd) };
        let result = sock.read_timeout();
        // 消耗 sock，阻止它关闭 fd
        let _ = sock.into_raw_fd(); // 忽略返回的 fd
        result
    }

    fn set_read_timeout(&self, duration: Option<Duration>) -> io::Result<()> {
        let fd = self.as_raw_fd();
        let sock = unsafe { Socket::from_raw_fd(fd) };
        let result = sock.set_read_timeout(duration);
        // 消耗 sock，阻止它关闭 fd
        let _ = sock.into_raw_fd();
        result
    }
}
// ... 使用示例同上 ...
```
*注意:* 这个方法仍然需要 `unsafe` 块来调用 `from_raw_fd`。

**3. 复制文件描述符 (`dup`)**

在调用 `from_raw_fd` 之前使用系统调用 `dup` 复制文件描述符。这样 `socket2::Socket` 获取的是复制后的 fd 的所有权，当它被 drop 时只会关闭这个复制品，不会影响原始的 fd。

```rust
use std::os::unix::io::{AsRawFd, FromRawFd, RawFd};
use std::io;
use std::time::Duration;
use socket2::Socket;
use tokio::net::UdpSocket;
// 使用 libc 或 nix crate 来复制 fd
// extern crate libc; // or use nix::unistd::dup;

fn dup_fd(fd: RawFd) -> io::Result<RawFd> {
    let new_fd = unsafe { libc::dup(fd) };
    if new_fd == -1 {
        Err(io::Error::last_os_error())
    } else {
        Ok(new_fd)
    }
}

pub trait SockOpt {
    fn read_timeout(&self) -> io::Result<Option<Duration>>;
    fn set_read_timeout(&self, duration: Option<Duration>) -> io::Result<()>;
}

impl SockOpt for tokio::net::UdpSocket {
    fn read_timeout(&self) -> io::Result<Option<Duration>> {
        let original_fd = self.as_raw_fd();
        let dup_fd = dup_fd(original_fd)?;
        // Socket 现在拥有 dup_fd 的所有权
        let sock = unsafe { Socket::from_raw_fd(dup_fd) };
        // 当 sock 被 drop 时，dup_fd 会被关闭，original_fd 不受影响
        sock.read_timeout()
    }

    fn set_read_timeout(&self, duration: Option<Duration>) -> io::Result<()> {
        let original_fd = self.as_raw_fd();
        let dup_fd = dup_fd(original_fd)?;
        let sock = unsafe { Socket::from_raw_fd(dup_fd) };
        sock.set_read_timeout(duration)
    }
}
// ... 使用示例同上 ...
```
*注意:* 这个方法引入了额外的系统调用 (`dup`)，并且仍然需要 `unsafe` 来调用 `from_raw_fd`。

**4. 直接使用 `libc`**

作为最后的手段，您可以直接使用 `libc` 库调用底层的 `setsockopt` 和 `getsockopt` 系统调用。这比较底层，需要您手动处理 `timeval` 结构和错误检查，并且是平台相关的。

**总结:**

最推荐的方法是使用 `socket2::SockRef`，因为它最安全、简洁，并且避免了 `unsafe` 代码块和所有权问题。如果无法使用 `SockRef`，使用 `into_raw_fd` 是对您现有代码改动最小的次优选择。复制文件描述符 (`dup`) 或直接使用 `libc` 也可以工作，但通常更复杂或更底层。

