   * @param {string | string[]} eventNames - A single event name string or an array of event name strings.
   * @param {...any} options - Additional arguments to pass to each callback function.
   */
  trigger(eventNames, ...options) {
    let namesToProcess = [];

    if (typeof eventNames === 'string') {
      namesToProcess.push(eventNames);
    } else if (Array.isArray(eventNames)) {
