   * Triggers one or more events, executing all subscribed callbacks with the provided options.
   *
   * @param {string|string[]} eventNames - The name of the event(s) to trigger. Can be a single string or an array of strings.
   * @param {...any} options - Additional arguments to pass to the callback functions.
   * @throws {TypeError} If eventNames is not a string or an array of strings.
   */
  trigger(eventNames, ...options) {
    let namesToTrigger = [];

    if (typeof eventNames === 'string') {
        if (eventNames.trim() === '') {
            console.warn("Trigger called with an empty event name string.");
            return;
        }
      namesToTrigger.push(eventNames);
    } else if (Array.isArray(eventNames)) {
      namesToTrigger = eventNames.filter(name => typeof name === 'string' && name.trim() !== '');
       if (namesToTrigger.length !== eventNames.length) {
            console.warn("Some invalid event names were ignored in the trigger array.");
       }
    } else {
      throw new TypeError('eventNames must be a string or an array of strings.');
    }

    namesToTrigger.forEach(eventName => {
      if (this._subscribers.has(eventName)) {
        // Iterate over a copy of the listeners array to prevent issues
        // if a callback modifies the subscription list (e.g., unsubscribes itself).
        const listeners = [...this._subscribers.get(eventName)];
        listeners.forEach(callback => {
          try {
            callback(...options);
          } catch (error) {
            console.error(`Error in event listener for "${eventName}":`, error);
            // Optionally, re-throw or handle specific errors
          }
        });
      }
    });
  }
}

