                const currentStepElement = document.getElementById(`step-${currentStep}`);
                if (!currentStepElement) return false;

                let isStepValid = true;
                // Find all validatable elements within the current step
                const elementsToValidate = $(currentStepElement).find('input, select, textarea').not(':disabled, [type=hidden]');

                elementsToValidate.each(function() {
                    if (!validator.element(this)) { // Use jQuery validation API
                        isStepValid = false;
                    }
                });
                return isStepValid;
            }

            nextBtn.addEventListener('click', function () {
