                // Final validation check before submitting (ensure last step is valid)
                if (!validateCurrentStep()) {
                    event.preventDefault(); // Stop submission if last step is invalid
                     console.log("Final validation failed before submit.");
                }
                // If validation passes, the form submits naturally to the server.
            });

            // Initialize the form display
            showStep(currentStep);
