import { APIRequestContext, expect } from '@playwright/test';

// Define interfaces for payloads and response data
export interface CreateUserPayload {
  // Add properties based on your actual API requirements
  // e.g., email: string; firstName: string; lastName: string;
  [key: string]: any; // Allow flexible properties for the example
}

export interface PermissionPayload {
  // Add properties based on your actual API requirements
  // e.g., role: string; permissions: string[];
  [key: string]: any; // Allow flexible properties for the example
}

export interface UserCredentials {
  username: string;
  password: string;
}

export interface UserInfo extends UserCredentials {
  id: string;
}

/**
 * Service class responsible for handling user-related API operations.
 */
export class UserService {
  private readonly request: APIRequestContext;
  private readonly userBasePath = '/users/v2';

  constructor(request: APIRequestContext) {
    this.request = request;
  }

  /**
   * Creates a new user via API.
   * @param payload - The payload for user creation.
   * @returns The ID of the created user.
   * @throws Error if the API call fails or returns an unexpected status.
   */
  async createUser(payload: CreateUserPayload): Promise<string> {
    const response = await this.request.post(`${this.userBasePath}/create`, {
      data: payload,
    });
    expect(response.status(), `Failed to create user. Status: ${response.status()}, Body: ${await response.text()}`).toBe(201);
    const json = await response.json();
    if (!json.id) {
      throw new Error('User creation response did not contain an ID.');
    }
    return json.id;
  }

  /**
   * Updates permissions for a given user via API.
   * @param userId - The ID of the user to update.
   * @param payload - The payload for permission updates.
   * @returns The user credentials (username, password) returned by the API.
   * @throws Error if the API call fails or returns an unexpected status.
   */
  async updatePermissions(userId: string, payload: PermissionPayload): Promise<UserCredentials> {
    const updatedPayload = { ...payload, id: userId };
    const response = await this.request.post(`${this.userBasePath}/permissions`, {
      data: updatedPayload,
    });
    expect(response.status(), `Failed to update permissions for user ${userId}. Status: ${response.status()}, Body: ${await response.text()}`).toBe(200);
    const json = await response.json();
     if (!json.username || !json.password) {
       throw new Error('Update permissions response did not contain username or password.');
     }
    return { username: json.username, password: json.password };
  }

  /**
   * Factory method to perform the common setup sequence:
   * create a user and then update their permissions.
   * @param createPayload - Payload for user creation.
   * @param permissionPayload - Payload for permission update.
   * @returns An object containing the user's ID and credentials.
   */
  async setupUserWithPermissions(
    createPayload: CreateUserPayload,
    permissionPayload: PermissionPayload
  ): Promise<UserInfo> {
    const userId = await this.createUser(createPayload);
    const credentials = await this.updatePermissions(userId, permissionPayload);
    return { id: userId, ...credentials };
  }
}

