// Service layer responsible for user-related API interactions

import { APIRequestContext } from '@playwright/test';
import {
  UserCreatePayload,
  PermissionPayload,
  CreatedUser,
  UserCredentials,
  UserSetupDetails,
} from './interfaces';

export class UserService {
  // Dependency Injection: Accepts the APIRequestContext
  constructor(private request: APIRequestContext) {}

  /**
   * Creates a new user via API.
   * @param payload Data for user creation.
   * @returns The created user's details (including ID).
   * @throws Error if the API request fails or returns an unexpected status.
   */
  private async createUser(payload: UserCreatePayload): Promise<CreatedUser> {
    const response = await this.request.post('/users/v2/create', {
      data: payload,
    });

    if (response.status() !== 201) {
      throw new Error(
        `Failed to create user. Status: ${response.status()}. Body: ${await response.text()}`
      );
    }
    const jsonResponse = await response.json();
    if (!jsonResponse.id) {
        throw new Error('Create user response is missing the "id" property.');
    }
    return jsonResponse as CreatedUser;
  }

  /**
   * Updates permissions for a given user ID via API.
   * @param userId The ID of the user whose permissions are being set.
   * @param payload Data for permission update.
   * @returns The user's credentials (username, password).
   * @throws Error if the API request fails or returns an unexpected status.
   */
  private async updateUserPermissions(
    userId: string,
    payload: PermissionPayload
  ): Promise<UserCredentials> {
    const updatedPayload = { ...payload, id: userId }; // Add user ID to the payload
    const response = await this.request.post('/users/v2/permissions', {
      data: updatedPayload,
    });

    if (response.status() !== 200) {
      throw new Error(
        `Failed to update permissions for user ${userId}. Status: ${response.status()}. Body: ${await response.text()}`
      );
    }
     const jsonResponse = await response.json();
     if (!jsonResponse.username || !jsonResponse.password) {
         throw new Error('Update permissions response is missing "username" or "password".');
     }
    return jsonResponse as UserCredentials;
  }

  /**
   * High-level method to orchestrate user creation and permission setup.
   * Encapsulates the multi-step API process.
   * @param createPayload Payload for creating the user.
   * @param permissionPayload Payload for setting permissions.
   * @returns Details including user ID and credentials.
   */
  async setupUserWithPermissions(
    createPayload: UserCreatePayload,
    permissionPayload: PermissionPayload
  ): Promise<UserSetupDetails> {
    // Step 1: Create the user
    const createdUser = await this.createUser(createPayload);

    // Step 2: Update permissions using the obtained user ID
    const credentials = await this.updateUserPermissions(
      createdUser.id,
      permissionPayload
    );

    // Step 3: Return the combined result
    return {
      userId: createdUser.id,
      username: credentials.username,
      password: credentials.password,
    };
  }

