// src/stores/rowStore.js
import { defineStore } from 'pinia';

export const useRowStore = defineStore('rowStore', {
  state: () => ({
    rows: [], // Array to hold the fetched rows
    loading: false, // Flag to indicate if data is being fetched
    hasMore: true, // Flag to indicate if more rows can be fetched
    nextStart: 0, // The starting index for the next fetch
    rowsPerFetch: 25, // How many rows to fetch per request
    totalRows: null, // Optional: Total number of rows available from the API
  }),
  actions: {
    async fetchRows() {
      // Prevent fetching if already loading or no more rows are available
      if (this.loading || !this.hasMore) {
        return;
      }

      this.loading = true;
      try {
        // Replace with your actual API endpoint
        const apiUrl = `https://api.example.com/data?start=${this.nextStart}&count=${this.rowsPerFetch}`;
        console.log(`Fetching from: ${apiUrl}`); // For debugging

        const response = await fetch(apiUrl);
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json(); // Assuming API returns { items: [...], total: number }

        if (data && data.items && data.items.length > 0) {
          this.rows.push(...data.items);
          this.nextStart += data.items.length; // Update the starting point for the next fetch

          // Update totalRows if it's the first fetch and the API provides it
          if (this.totalRows === null && data.total !== undefined) {
             this.totalRows = data.total;
          }

          // Check if there are more rows to load
          // Option 1: Based on total count (if available)
          if (this.totalRows !== null) {
             this.hasMore = this.rows.length < this.totalRows;
          }
          // Option 2: Based on whether the last fetch returned fewer items than requested
          else {
             this.hasMore = data.items.length === this.rowsPerFetch;
          }

        } else {
          // No more rows returned from the API
          this.hasMore = false;
        }

      } catch (error) {
        console.error("Failed to fetch rows:", error);
        // Optionally handle the error state in the UI
        this.hasMore = false; // Stop trying to fetch on error
      } finally {
        this.loading = false;
      }
    },
    // Optional: Action to reset the store state if needed (e.g., for filtering/sorting)
    reset() {
      this.rows = [];
      this.loading = false;
      this.hasMore = true;
      this.nextStart = 0;
      this.totalRows = null;
    }
  }
});
```

