#include <numeric> // Required for std::iota
#include <algorithm> // Required for std::erase (in C++20, otherwise use vector::erase)

class Solution {
public:
    std::string getPermutation(int n, int k) {
        // 1. Precompute factorials [0!, 1!, ..., (n-1)!]
        std::vector<int> factorial(n);
        factorial[0] = 1;
        for (int i = 1; i < n; ++i) {
            // Check for potential overflow, although n<=9 makes it safe for int
            if (factorial[i - 1] > 2147483647 / i) {
                 // Handle potential overflow if constraints were larger
                 // For n <= 9, this won't happen.
                 return "Error: Factorial overflow"; // Or throw
            }
            factorial[i] = factorial[i - 1] * i;
        }

        // 2. Create list of numbers [1, 2, ..., n]
        std::vector<int> numbers(n);
        std::iota(numbers.begin(), numbers.end(), 1); // Fills with 1, 2, ..., n

        // 3. Adjust k to be 0-based index
        k--; // k is now in the range [0, n!-1]

        // 4. Build the permutation string
        std::string result = "";
        for (int i = n; i >= 1; --i) {
            // i = number of elements remaining
            // (i-1)! is the size of permutations for the remaining digits
            int index = k / factorial[i - 1];

            // Append the chosen digit (convert int to string/char)
            result += std::to_string(numbers[index]);

            // Remove the chosen number from the list
            numbers.erase(numbers.begin() + index);

            // Update k for the subproblem
            k %= factorial[i - 1];
        }

        return result;
    }
};
