class Solution {
public:
    /**
     * @brief Finds the k-th permutation of the sequence [1, 2, ..., n].
     * 
     * @param n The size of the set [1, 2, ..., n].
     * @param k The index (1-based) of the desired permutation.
     * @return std::string The k-th permutation as a string.
     * 
     * The algorithm works by determining each digit of the permutation from left to right.
     * For the first digit, there are n choices. The permutations are grouped based on the first digit.
     * Each group has (n-1)! permutations. By dividing k (adjusted to 0-based index) by (n-1)!, 
     * we can find which group the k-th permutation belongs to, thus determining the first digit.
     * We then update k to be the index within that group (using the modulo operator) and remove the chosen digit 
     * from the available numbers. We repeat this process for the remaining digits with the remaining numbers 
     * and the corresponding smaller factorials.
     */
    std::string getPermutation(int n, int k) {
        // Step 1: Precompute factorials from 0! to n!
        std::vector<int> fact(n + 1);
        fact[0] = 1;
        for (int i = 1; i <= n; ++i) {
            // Check for potential overflow, though with n <= 9, this is safe.
            // 9! = 362,880, which fits comfortably within a standard 32-bit integer.
            fact[i] = fact[i - 1] * i;
        }

        // Step 2: Initialize a list of available numbers [1, 2, ..., n]
        std::vector<int> nums(n);
        std::iota(nums.begin(), nums.end(), 1); // Fills nums with 1, 2, ..., n

        // Step 3: Adjust k to be 0-based index (k-1) for calculations
        k--; 

        std::string result = "";

        // Step 4: Determine each digit of the permutation
        for (int i = n; i >= 1; --i) {
            // i represents the number of elements remaining to be chosen.
            // The permutations of the remaining (i-1) elements number fact[i-1].

            // Calculate the index of the digit to pick from the current 'nums' list
            int index = k / fact[i - 1];

            // Append the selected number to the result string
            result += std::to_string(nums[index]);

            // Remove the selected number from the list of available numbers
            // vector::erase is O(N) where N is the number of elements after the erased position.
            // Since this loop runs n times, this part contributes O(n^2) to the complexity.
            nums.erase(nums.begin() + index);

            // Update k for the next iteration (index within the subgroup)
            k %= fact[i - 1];
        }

        // Step 5: Return the constructed permutation string
        return result;
    }
};
