// Global vector to store unique sorted y-coordinates for discretization
vector<ll> y_coords;
// Global map to quickly find the index corresponding to a y-coordinate
map<ll, int> y_map;
// Global vector representing the segment tree
vector<Node> tree;

// Function to update the segment tree
// node: index of the current node in the tree (1-based)
// start, end: indices in y_coords defining the interval covered by this node [y_coords[start], y_coords[end])
// l, r: indices in y_coords defining the target interval to update [y_coords[l], y_coords[r])
// val: value to add to the count (+1 or -1)
void update(int node, int start, int end, int l, int r, int val) {
    // If the target interval is completely outside the current node's interval, return
    if (r <= start || end <= l) {
        return;
    }
    // If the target interval completely covers the current node's interval
    if (l <= start && end <= r) {
        tree[node].count += val; // Update the coverage count
    } else {
        // Otherwise, recurse down to children
        int mid = start + (end - start) / 2;
        update(node * 2, start, mid, l, r, val);       // Update left child
        update(node * 2 + 1, mid, end, l, r, val);     // Update right child
    }

    // After updating count (or counts in children), recalculate the covered length for this node
    if (tree[node].count > 0) {
        // If count > 0, this node's entire interval is covered by at least one rectangle
        tree[node].length = y_coords[end] - y_coords[start];
    } else {
        // If count == 0, this node's interval is not fully covered itself.
        // Its covered length is the sum of its children's covered lengths.
        // Check if it's a leaf node (base case for recursion).
        if (end - start == 1) { // Leaf node corresponds to a single elementary interval
            tree[node].length = 0; // If count is 0, leaf's length is 0
        } else { // Internal node
             tree[node].length = tree[node * 2].length + tree[node * 2 + 1].length;
        }
    }
}

