    t = std::max(0.0, std::min(1.0, t));

    // Calculate the closest point on the segment
    Point closest_point = a + ab * t;

    // Return the distance between P and the closest point
    return norm(p - closest_point);
}

// Check if segment graphic S is completely covered by segment graphic T
bool isSegmentCovered(const SegmentGraphic& S, const SegmentGraphic& T, double tolerance = 1e-9) {
