    double dist_start = pointSegmentDistance(S.start, T.start, T.end);

    // 4. Calculate distance from S.end to segment T.start-T.end
    double dist_end = pointSegmentDistance(S.end, T.start, T.end);

    // 5. Check if both distances are within the allowed maximum (using tolerance)
