public class StaircasePathsFinder {

    /**
     * Finds all possible ways to climb n stairs taking 1 or 2 steps at a time.
     *
     * @param n             The total number of stairs.
     * @param currentPath   The list representing the sequence of steps taken so far.
     * @param allPaths      The list to store all valid paths found.
     * @param remainingSteps The number of steps remaining to climb.
     */
    private static void findPathsRecursive(int n, List<Integer> currentPath, List<List<Integer>> allPaths, int remainingSteps) {
        // Base case: Successfully reached the top (no steps remaining)
        if (remainingSteps == 0) {
            // Add a copy of the current path to the list of all paths
            allPaths.add(new ArrayList<>(currentPath));
            return;
        }

        // Base case: Overshot the target (cannot reach the top with this path)
        if (remainingSteps < 0) {
            return;
        }

        // Explore taking 1 step
        currentPath.add(1);
        findPathsRecursive(n, currentPath, allPaths, remainingSteps - 1);
        // Backtrack: Remove the last step (1) to explore other possibilities
        currentPath.remove(currentPath.size() - 1);

        // Explore taking 2 steps
        currentPath.add(2);
        findPathsRecursive(n, currentPath, allPaths, remainingSteps - 2);
        // Backtrack: Remove the last step (2)
        currentPath.remove(currentPath.size() - 1);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("请输入台阶总数 n: ");
        int n = scanner.nextInt();
        scanner.close();

        if (n < 0) {
            System.out.println("台阶数不能为负数。");
            return;
        }

        List<List<Integer>> allPaths = new ArrayList<>();
        List<Integer> currentPath = new ArrayList<>();

        // Start the recursive process
        findPathsRecursive(n, currentPath, allPaths, n);

        // Output the results
        System.out.println("走完 " + n + " 级台阶的所有方法如下：");
        if (allPaths.isEmpty() && n == 0) {
