#include <limits> // Required for numeric_limits

// Structure to store letter and its original index (1-based)
struct LetterInfo {
    char letter;
    int index;

    // Comparison for finding minimum: prioritize smaller letter, then smaller index
    bool operator<(const LetterInfo& other) const {
        if (letter != other.letter) {
            return letter < other.letter;
        }
        return index < other.index;
    }
};

// Default value for nodes representing invalid ranges or uninitialized data
const LetterInfo INVALID_INFO = {{'{', std::numeric_limits<int>::max()}}; // '{' is > 'z'

// Segment tree node structure (simplified)
struct SegTreeNode {
    LetterInfo min_info;
};

// Global variables for segment tree
std::vector<SegTreeNode> tree;
std::vector<LetterInfo> base_array;
int n_seg_base; // Size of the base array (m)
int n_seg_tree; // Size for tree array (power of 2 >= m)

// Combine function for segment tree nodes
LetterInfo combine(const LetterInfo& a, const LetterInfo& b) {
    return std::min(a, b);
}

// Build segment tree (recursive version)
void build(int node, int start, int end) {
    if (start == end) {
        if (start < n_seg_base) {
            tree[node] = {{base_array[start].letter, base_array[start].index}};
        } else {
            // Initialize nodes outside the range [0, m-1] with an invalid value
            tree[node] = {INVALID_INFO};
        }
    } else {
        int mid = start + (end - start) / 2;
        build(2 * node, start, mid);
        build(2 * node + 1, mid + 1, end);
        tree[node].min_info = combine(tree[2 * node].min_info, tree[2 * node + 1].min_info);
    }
}

// Query segment tree for range [l, r] (0-based indices)
LetterInfo query(int node, int start, int end, int l, int r) {
    if (r < start || end < l || l > r) { // Added l > r check for empty range
        // Range outside query range or invalid range
        return INVALID_INFO;
    }
    if (l <= start && end <= r) {
        // Range fully contained in query range
        return tree[node].min_info;
    }
    // Range partially overlaps query range
    int mid = start + (end - start) / 2;
    LetterInfo p1 = query(2 * node, start, mid, l, r);
    LetterInfo p2 = query(2 * node + 1, mid + 1, end, l, r);
    return combine(p1, p2);
}


