```cpp
#include <iostream>
#include <vector>
#include <string>
#include <vector>
#include <algorithm>
#include <limits>

// Node for segment tree storing minimum char and its smallest index (1-based)
struct Node {
    char c = '{'; // Character lexicographically larger than 'z'
    int index = std::numeric_limits<int>::max();
};

// Combine function for segment tree nodes
Node combine(const Node& a, const Node& b) {
    if (a.c < b.c) return a;
    if (b.c < a.c) return b;
    // If chars are equal, choose the node with the smaller index
    return (a.index < b.index) ? a : b;
}

// Build segment tree (recursive version)
void build(const std::vector<std::pair<char, int>>& data, std::vector<Node>& tree, int v, int tl, int tr) {
    if (tl == tr) {
        if (tl < data.size()) {
            tree[v] = {data[tl].first, data[tl].second};
        } else {
            // Initialize with default values if index out of bounds
             tree[v] = {'{', std::numeric_limits<int>::max()};
        }
    } else {
        int tm = tl + (tr - tl) / 2;
        build(data, tree, 2 * v, tl, tm);
        build(data, tree, 2 * v + 1, tm + 1, tr);
        tree[v] = combine(tree[2 * v], tree[2 * v + 1]);
    }
}

// Query segment tree for range [l, r] (0-based indices for query range)
Node query(const std::vector<Node>& tree, int v, int tl, int tr, int l, int r) {
    if (l > r) {
        // Return default node for empty or invalid range
        return {'{', std::numeric_limits<int>::max()};
    }
    if (l == tl && r == tr) {
        return tree[v];
    }
    int tm = tl + (tr - tl) / 2;
    Node left_result = query(tree, 2 * v, tl, tm, l, std::min(r, tm));
    Node right_result = query(tree, 2 * v + 1, tm + 1, tr, std::max(l, tm + 1), r);
    return combine(left_result, right_result);
}


