        result.x = 1;
        result.y = 0;
        return result;
    }

    // Bước (2): Khởi tạo giá trị
    x2 = 1; x1 = 0; y2 = 0; y1 = 1;

    // Bước (3): Vòng lặp while b > 0
    while (b > 0) {
        // Bước 3.1: Tính q, r, x_temp, y_temp
        q = a / b; // Trong C, phép chia số nguyên tự động làm tròn xuống
        r = a - q * b; // Hoặc có thể dùng r = a % b;
        x_temp = x2 - q * x1;
        y_temp = y2 - q * y1;

        // Bước 3.2: Cập nhật a, b và các hệ số
        // Lưu ý: Thứ tự cập nhật quan trọng
        a = b;
        b = r;
        x2 = x1;
        x1 = x_temp;
        y2 = y1;
        y1 = y_temp;
