function [end_pos, T_total] = forward_kinematics(theta)
    global DH_params;
    T_total = eye(4);
    num_joints = size(DH_params, 1);
    if length(theta) ~= num_joints
        error('Input theta length mismatch');
    end
    for i = 1:num_joints
        T_link = dh_matrix(DH_params(i,:), theta(i));
        T_total = T_total * T_link;
    end
    end_pos = T_total(1:3,4); % Position vector [x; y; z] in mm
end

% DH矩阵计算 (Standard DH)
function T = dh_matrix(dh_row, theta_i)
    a = dh_row(1);      % Link length (mm)
    alpha = deg2rad(dh_row(2)); % Link twist (rad)
    d = dh_row(3);      % Link offset (mm)
    % theta_i is the joint angle (rad)

    T = [ cos(theta_i), -sin(theta_i)*cos(alpha),  sin(theta_i)*sin(alpha), a*cos(theta_i);
          sin(theta_i),  cos(theta_i)*cos(alpha), -cos(theta_i)*sin(alpha), a*sin(theta_i);
          0,           sin(alpha),             cos(alpha),            d;
          0,           0,                      0,                     1 ];
end

